PROBE = os.path.join(CAMPAIGN, "probe.py")


def stub_config(_tmp, kill_mode="arm-kill-tree"):
    config = {
        "arms": {arm: {"executable": sys.executable, "templates": {
            "fast": [STUB, "arm-fast", "{timeout_s}", "--", "{child}", "{child_args}"],
            "kill": [STUB, kill_mode, "{timeout_s}", "--", "{child}", "{child_args}"],
        }} for arm in plan_mod.PRODUCT_ARMS},
        "children": {
            "fast": {"program": sys.executable, "args": [STUB, "exit0"]},
            "floor_spawn": {"program": sys.executable, "args": [STUB, "exit0b"]},
            "kill": {"program": sys.executable,
                     "args": [STUB, "tree", "{marker}", "{sleep_s}"]},
            "scale_wide": {"program": sys.executable,
                           "args": [STUB, "wide", "{width}", "{ids}",
                                    "{sleep_s}", "{sleep_s}"]},
            "scale_deep": {"program": sys.executable,
                           "args": [STUB, "deep", "1", "{depth}",
                                    "{dir}", "{sleep_s}"]},
        },
        "survivor_checker": [sys.executable, PROBE],
    }
    # The Python fixture returns 124 on every tree timeout. The pinned
    # ProcessKit executable returns 106 in the Windows campaign.
    config["arms"]["processkit"]["expected_exit"] = {"kill": 124}
    return config


FIXTURE_STDOUT = b"ptg-output-stdout\n"
FIXTURE_STDERR = b"error-stream\n"


_SHIPPED_CONFIG = None

# Count the executable and the expanded fast child (testkit relay 0).
# The pinned nuewframe form requires a separator before the child.
# ProcessKit also takes a timeout flag, an event path, and stdin forwarding.
SHIPPED_FAST_ARGV_LENGTHS = {
    "guard": 7, "nuewframe": 6, "processkit": 11, "sysprims": 6,
}


def shipped_config():
    """The suite's shipped campaign configuration
    (campaign.json), loaded once — the plan both perfect
    fixtures' argv are built through (round-36 F3)."""
    global _SHIPPED_CONFIG
    if _SHIPPED_CONFIG is None:
        cfg_path = os.path.join(HERE, "..", "campaign.json")
        with open(cfg_path, encoding="utf-8") as handle:
            _SHIPPED_CONFIG = json.load(handle)
    return _SHIPPED_CONFIG


def fixture_fast_argv(arm):
    """The fast vector the shipped construction builds for
    one product arm: the executable token plus the arm's
    fast template from the shipped configuration expanded
    with its fast child spec — the vector runner.run_slot
    writes on a fast record, at the plan's own length
    (round-36 F3 construction truth: the fixture previously
    stamped a generic 4-token vector on every arm, a fast
    length no shipped template produces)."""
    config = shipped_config()
    exe = arms_mod.arm_executable(arm, config)
    spec = config["children"]["fast"]
    return [exe] + arms_mod.expand_template(
        arms_mod.resolve_template(arm, "fast", config),
        runner_mod.FAST_TIMEOUT_S, spec["program"],
        list(spec.get("args", [])))


def measured(arm, ms, path="fast", context="NO_WINDOW", rep=0, outcome="ok",
             kind="measured", exit_code=None, detail=""):
    if exit_code is None:
        # Malformed records carry the arm's recorded answer to
        # the shape (125 here, the refusal the fixture arms give);
        # no expected code is pinned for that path as a whole —
        # round-31 F2 pins 125 for the designated arm's
        # contract-pinned shapes only, which is exactly the code
        # this fixture's designated records carry.
        exit_code = 125 if path == "malformed" else \
            arms_mod.expected_exit(arm, path)
    # Construction truth (round-25 alignment, logged in the
    # round-25 landing record): the runner writes argv (the
    # executed argument vector, a non-empty list of string
    # tokens) and arm_pid (the spawned arm's own PID) on EVERY
    # record, fast and control included. The fixture previously
    # stamped argv=[] on every record and arm_pid on kill
    # records only — shapes no run writes, on which round 24's
    # fast-arm_pid withdrawal rested; the fixture now carries
    # both fields at the runner's breadth.
    record = {"kind": kind, "arm": arm, "path": path, "context": context,
              "rep": rep, "outcome": outcome, "elapsed_ms": ms,
              "exit_code": exit_code,
              "variant": plan_mod.variant_for(path, rep, kind),
              "survivor": False if path in ("kill", "scale") else None,
              # Construction truth (round-36 F3): a product
              # arm's fast record carries the vector the
              # shipped construction builds for that arm, at
              # the plan's length per arm; the floor arms and
              # the kill/scale paths keep the generic vector
              # (no hold reads their argv length).
              "argv": fixture_fast_argv(arm) if (
                  path == "fast" and arm in plan_mod.PRODUCT_ARMS)
              else ["fixture-arm", "10", "--", "fixture-child"],
              "arm_pid": 40000 + rep,
              "detail": detail,
              # The runner's resource instrumentation (round-26):
              # every record carries the arm's counters or a note;
              # the fixture's arms are accounted, so it carries
              # the counters.
              "cpu_ms": 1.0, "peak_working_set_bytes": 4096,
              "resource_note": None,
              "descendant_pids": None,
              "output_stdout_sha256": None, "output_stderr_sha256": None,
              "output_stdout_len": None, "output_stderr_len": None,
              "output_stdout_match": None, "output_stderr_match": None}
    if path == "malformed":
        # Construction truth (round-33 F2; round-36 F3): a
        # malformed record's argv is the executed vector
        # presenting its slot's shape — the runner's own
        # malformed_argv construction through the arm's
        # template under the shipped configuration, so the
        # vector carries the shape's distinguishing content
        # (the nonexistent program token, the malformed /
        # out-of-range timeout texts, the empty child token,
        # the 4096-character argument, the lone-surrogate
        # argument) at the plan's own length for the arm.
        # The fixture previously hand-stamped per-shape
        # vectors at a generic 4/5-token length no shipped
        # template produces.
        record["argv"] = runner_mod.malformed_argv(
            plan_mod.Slot(kind, arm, path, context, rep,
                          record["variant"]), shipped_config())
    if path == "fast" and outcome == "ok":
        # A correct fast record carries the output observation the
        # runner records: both streams' digests and lengths and a
        # match verdict against the expected bytes. Kill records
        # carry none (the kill child's product is its tree).
        import hashlib
        record["output_stdout_sha256"] = hashlib.sha256(
            FIXTURE_STDOUT).hexdigest()
        record["output_stderr_sha256"] = hashlib.sha256(
            FIXTURE_STDERR).hexdigest()
        record["output_stdout_len"] = len(FIXTURE_STDOUT)
        record["output_stderr_len"] = len(FIXTURE_STDERR)
        record["output_stdout_match"] = True
        record["output_stderr_match"] = True
    if path in ("kill", "scale"):
        # A kill record carries the tree identity the runner
        # records for every kill slot: the arm's PID, the child
        # and grandchild PIDs read from the slot's marker files,
        # and the marker path itself (runner.py's record shape).
        # Without them the record's survivor classification rests
        # on an identity the record does not carry, and the
        # record-consistency discipline names it inconsistent.
        # A scale record carries the same identity shape, with
        # its published descendant list beside the first of them.
        record["arm_pid"] = 40000 + rep
        record["child_pid"] = 50000 + rep
        record["grandchild_pid"] = 60000 + rep
        record["tree_marker"] = f"fixture-marker-{context}-{rep}"
        if path == "scale":
            # Construction truth (round-27 alignment): a scale
            # record publishes exactly its variant's descendant
            # count — wide-N publishes N, deep-D (levels 1..D)
            # publishes D — the count the runner's classification
            # and the checker's ok-record rule both hold.
            owed = plan_mod.expected_descendants(
                plan_mod.variant_for("scale", rep, kind))
            record["descendant_pids"] = [
                60000 + rep * 100 + index for index in range(owed)]
            record["grandchild_pid"] = record["descendant_pids"][0]
    return record


def complete_records():
    """One correct record per plan slot, built from the plan itself:
    the guard wins or ties every median, both floor arms agree in
    both contexts, every exit code matches the expected table,
    every fast slot's output matches the expected bytes, and
    no kill slot leaves a survivor."""
    recs = []
    for slot in plan_mod.build_plan():
        if slot.arm == "floor-direct":
            ms = 51.0
        elif slot.arm == "floor-spawn":
            ms = 52.0
        elif slot.arm == "guard":
            ms = 62.0 if slot.path == "fast" else 2100.0
        else:
            ms = 65.0 if slot.path == "fast" else 2200.0
        recs.append(measured(slot.arm, ms, path=slot.path,
                             context=slot.context, rep=slot.rep,
                             kind=slot.kind))
    return recs


