@contextlib.contextmanager
def collected_usability_artifact():
    """The manual usability instrument with its check performed:
    a usability artifact in which one prompt class was exercised
    and its observed outcome recorded (the state the ready-to-fly
    Windows run leaves behind), patched in as report's artifact.
    Round-27: dimension (8)'s state is computed from this
    artifact, so a completeness proof over the shipped decisions
    carries the performed check as part of its premise — the
    as-shipped artifact (every outcome "not-run") renders the
    dimension UNEVALUATED and no campaign over it completes."""
    artifact = {
        "instrument": "fixture manual usability check",
        "tier": "manual/Windows-theory",
        "records": [
            {"prompt_class": "Windows Hello request",
             "exercised": True,
             "observed": "fixture: prompt shown, answered "
                         "correctly, run proceeded",
             "outcome": "pass"},
            {"prompt_class": "credential dialog",
             "exercised": False,
             "observed": None, "outcome": "not-run"},
            {"prompt_class": "console password prompt",
             "exercised": False,
             "observed": None, "outcome": "not-run"},
        ],
    }
    with tempfile.NamedTemporaryFile(
            "w", suffix=".json", delete=False,
            encoding="utf-8") as handle:
        json.dump(artifact, handle)
        path = handle.name
    try:
        with mock.patch.object(report_mod, "USABILITY_ARTIFACT", path):
            yield path
    finally:
        os.unlink(path)

# The degraded set (round-25 P1): the verifications the
# preserved reduced-run package's absent configuration anchor
# degrades, each named unverifiable by check_run_package.
# Round 24 named only config_templates; the naming duty is
# general now, and the genuine package's named-unverifiable
# set is exactly this set, no more and no less.
UNVERIFIABLE_DEGRADED = (
    "config_templates", "competitor identity",
    "expected-output", "profile decisions",
    # Round-37 F3: the argv length budget joins the list —
    # round 36 made the absent anchor degrade it (the
    # NO_VERIFIED_PLAN sentinel derives no budget for any
    # arm) without adding it to the naming, against the
    # list's own stated duty.
    "argv length budget")


def assert_degraded_unverifiable_set(testcase, problems):
    testcase.assertEqual(len(problems), len(UNVERIFIABLE_DEGRADED),
                         problems)
    for problem in problems:
        testcase.assertIn("unverifiable", problem)
    for needle in UNVERIFIABLE_DEGRADED:
        testcase.assertTrue(
            any(needle in problem for problem in problems),
            (needle, problems))


def with_outcomes(records, arm, path, outcome, kind=None, context=None):
    """A copy of `records` with every matching slot reclassified to
    `outcome` (arm and path always match; kind and context match
    when given). Slot identity is untouched, so exact slot
    accounting against the plan still holds."""
    out = []
    for record in records:
        record = dict(record)
        if record["arm"] == arm and record["path"] == path \
                and (kind is None or record["kind"] == kind) \
                and (context is None or record["context"] == context):
            record["outcome"] = outcome
            if outcome == "descendant-survived":
                record["survivor"] = True
            elif outcome == "infra-failure":
                record["survivor"] = None
                record["detail"] = "fixture infrastructure failure"
        out.append(record)
    return out


def gate_entry(records, dimension, context):
    return next(entry for entry in report_mod.freeze_gate(records)
                if entry["dimension"] == dimension
                and entry["context"] == context)


def probe_evidence(prices):
    """A pricing-probe evidence object of the shape
    pricing.prices_from_observations builds: a reference to recorded
    probe observations (kind tag, guard fingerprint, per-item probe
    trace), never a bare dict of numbers."""
    return {
        "kind": "pricing-probe-evidence",
        "guard_fingerprint": ["a" * 64],
        "observation_count": 2 * len(prices),
        "items": {item: {"ms": ms, "probe": "test-probe",
                         "paired_observations": 9,
                         "trace": f"probe test-probe, 9 paired "
                                  f"observations"}
                  for item, ms in prices.items()},
    }


class PlanTests(unittest.TestCase):
    def test_plan_totals_match_configured_decomposition(self):
        counts = plan_mod.check_plan(plan_mod.build_plan())
        # Internal consistency: each count is derived from the
        # plan's own configured structure (floor/product arms x
        # paths x contexts x the rep constants), so a built plan
        # is validated against its own decomposition — dropped,
        # duplicated or misplaced slots — not against a mandate.
        derived = {
            "control": len(plan_mod.FLOOR_ARMS)
            * len(plan_mod.CONTEXTS) * plan_mod.CONTROL_REPS,
            "warmup": len(plan_mod.PRODUCT_ARMS) * len(plan_mod.PATHS)
            * len(plan_mod.CONTEXTS) * plan_mod.WARMUP_REPS
            + len(plan_mod.MALFORMED_SHAPES) * len(plan_mod.PRODUCT_ARMS)
            * len(plan_mod.CONTEXTS) * plan_mod.MALFORMED_WARMUP_REPS
            + len(plan_mod.SCALE_VARIANTS) * len(plan_mod.PRODUCT_ARMS)
            * len(plan_mod.CONTEXTS) * plan_mod.SCALE_WARMUP_REPS,
            "measured": len(plan_mod.PRODUCT_ARMS)
            * len(plan_mod.PATHS) * len(plan_mod.CONTEXTS)
            * plan_mod.MEASURED_REPS
            + len(plan_mod.MALFORMED_SHAPES) * len(plan_mod.PRODUCT_ARMS)
            * len(plan_mod.CONTEXTS) * plan_mod.MALFORMED_REPS
            + len(plan_mod.SCALE_VARIANTS) * len(plan_mod.PRODUCT_ARMS)
            * len(plan_mod.CONTEXTS) * plan_mod.SCALE_REPS,
        }
        self.assertEqual(counts, derived)
        self.assertEqual(counts, FULL_COUNTS)
        self.assertEqual(plan_mod.EXPECTED_TOTAL, sum(derived.values()))
        # Current configuration, stated as the current
        # configuration: 1,940 slots as configured (the round-26
        # measurement-argument resize: 1,620 remains the reference
        # decomposition of the original fast/kill plan shape; the
        # malformed and scaling cells the argument yields bring
        # the configured total to 1,940). This is a configuration
        # pin, not a correctness requirement — an argued resize
        # re-pins it as part of its change.
        self.assertEqual(sum(counts.values()), 1940)

    def test_six_arms_and_two_contexts_kept_separate(self):
        slots = plan_mod.build_plan()
        self.assertEqual({s.arm for s in slots}, set(plan_mod.ARMS))
        self.assertEqual(len(plan_mod.ARMS), 6)
        measured_contexts = {s.context for s in slots if s.kind == "measured"}
        self.assertEqual(measured_contexts, {"NO_WINDOW", "DETACHED"})

    def test_controls_are_floor_arms_only_and_fast_only(self):
        for slot in plan_mod.build_plan():
            if slot.kind == "control":
                self.assertIn(slot.arm, plan_mod.FLOOR_ARMS)
                self.assertEqual(slot.path, "fast")

    def test_reduced_plan_is_a_prefix(self):
        slots = plan_mod.build_plan()
        self.assertEqual(slots[:50], plan_mod.build_plan()[:50])
        self.assertEqual(slots[0].kind, "control")


class TemplateTests(unittest.TestCase):
    def test_template_expansion_splices_child(self):
        out = arms_mod.expand_template(
            ["{timeout_s}", "--", "{child}", "{child_args}"], 2.0, "prog", ["a", "b"])
        self.assertEqual(out, ["2", "--", "prog", "a", "b"])

    def test_template_ms_form(self):
        out = arms_mod.expand_template(["timeout", "{timeout_ms}", "{child}"], 2.0, "p", [])
        self.assertEqual(out, ["timeout", "2000", "p"])

    def test_guard_template_carries_timeout_flag(self):
        template = arms_mod.resolve_template("guard", "fast", {})
        self.assertEqual(template[0], "--timeout")


class FloorAndReportTests(unittest.TestCase):
    def records(self, guard_ms=62.0, direct=51.0, spawn=50.0):
        recs = [measured("floor-direct", direct, kind="control"),
                measured("floor-spawn", spawn, kind="control"),
                measured("guard", guard_ms)]
        for arm in ("processkit", "nuewframe", "sysprims"):
            recs.append(measured(arm, 55.0))
        return recs

    def test_floor_is_the_agreement_of_the_minimal_tools(self):
        floor, agreed = report_mod.floor_ms(self.records(), "NO_WINDOW")
        self.assertTrue(agreed)
        self.assertEqual(floor, 51.0)

    def test_floor_refused_when_the_minimal_tools_disagree(self):
        floor, agreed = report_mod.floor_ms(
            self.records(direct=51.0, spawn=90.0), "NO_WINDOW")
        self.assertFalse(agreed)

    def test_floor_tolerance_matches_the_bundle_agreement(self):
        # The bundle's two minimal tools: 50.9 ms and 52.5 ms, a
        # spread of 1.6 ms (3.0% of the larger). They must agree
        # under the derived tolerance; tools 10% apart must not.
        self.assertEqual(report_mod.FLOOR_AGREEMENT_TOLERANCE, 0.05)
        _floor, agreed = report_mod.floor_ms(
            self.records(direct=50.9, spawn=52.5), "NO_WINDOW")
        self.assertTrue(agreed)
        _floor, agreed = report_mod.floor_ms(
            self.records(direct=50.9, spawn=56.5), "NO_WINDOW")
        self.assertFalse(agreed)

    def test_no_distance_reported_when_the_floor_arms_disagree(self):
        recs = self.records(direct=51.0, spawn=90.0)
        decomp = report_mod.decompose(recs, pricing=None, context="NO_WINDOW")
        self.assertIn("status", decomp)
        text = report_mod.render(recs, FULL_COUNTS, {"guard": {}})
        self.assertNotIn("distance above floor:", text)

    def test_warmup_records_do_not_move_the_headline_medians(self):
        recs = self.records()
        for rep in range(9):
            recs.append(measured("guard", 5000.0, rep=rep, kind="warmup"))
            recs.append(measured("floor-direct", 5000.0, rep=rep,
                                 kind="warmup"))
        floor, agreed = report_mod.floor_ms(recs, "NO_WINDOW")
        self.assertTrue(agreed)
        self.assertEqual(floor, 51.0)
        decomp = report_mod.decompose(recs, pricing=None, context="NO_WINDOW")
        self.assertEqual(decomp["guard_fast_median_ms"], 62.0)

    def test_report_headline_is_distance_above_floor_not_a_race(self):
        text = report_mod.render(self.records(), FULL_COUNTS, {"guard": {}})
        self.assertIn("distance above floor: 11.000 ms", text)
        self.assertIn("INCOMPLETE", text)  # only 1 measured slot ran

    def test_stale_pairing_appears_only_with_provenance(self):
        text = report_mod.render(self.records(), FULL_COUNTS, {"guard": {}})
        self.assertIn("66.5", text)
        self.assertIn("predates the gauntlet", text)

    def test_nuewframe_facts_stated_exactly(self):
        facts = report_mod.NUEWFRAME_KILL_FACTS
        self.assertIn("does not kill descendants at all", facts)
        self.assertIn("TerminateProcess on the direct child handle", facts)
        self.assertIn("5 s wait", facts)
        self.assertIn("unimplemented on Windows", facts)
        self.assertIn("killed nothing", facts)

    def test_decomposition_prices_only_the_expensive_class(self):
        decomp = report_mod.decompose(
            self.records(), pricing=probe_evidence({
                "owner verification": 3.0,
                "console probe + console finish": 4.0}),
            context="NO_WINDOW")
        self.assertEqual(set(decomp["items"]), set(report_mod.EXPENSIVE_CLASS))
        self.assertIsNone(decomp["items"]["resolver probe count"]["ms"])
        self.assertEqual(decomp["items"]["owner verification"]["tier"],
                         "measured (pricing probe)")
        self.assertAlmostEqual(decomp["unexplained_ms"], 11.0 - 7.0)

    def test_guard_descendant_survival_is_a_standing_loss(self):
        recs = self.records()
        bad = measured("guard", 3000.0, path="kill", outcome="descendant-survived")
        recs.append(bad)
        losses = report_mod.standing_losses(recs, FULL_COUNTS)
        self.assertTrue(any("descendant" in loss for loss in losses))

    def test_complete_campaign_has_no_standing_losses(self):
        recs = complete_records()
        self.assertEqual(len(recs), plan_mod.EXPECTED_TOTAL)
        losses = report_mod.standing_losses(recs, FULL_COUNTS)
        self.assertEqual(losses, [])
        text = report_mod.render(recs, FULL_COUNTS, {"guard": {}})
        self.assertIn("fast-path latency: PASS", text)
        self.assertIn("kill-path correctness: PASS", text)
        # Slot/freeze standing losses are empty, but the campaign
        # still renders INCOMPLETE: the evaluation profile's
        # unobserved dimensions are UNEVALUATED (see
        # ProfileDimensionTests).
        self.assertIn("STATUS: INCOMPLETE", text)
        self.assertNotIn("STATUS: complete campaign", text)


class FloorSpawnTests(unittest.TestCase):
    """Both floor arms are real process spawns of distinct minimal
    exit-at-once programs, so their agreement is empirical."""

    def test_both_floor_arms_are_real_process_spawns(self):
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            from plan import Slot
            for arm in plan_mod.FLOOR_ARMS:
                rec = run_slot(Slot("control", arm, "fast", "NO_WINDOW", 0),
                               config)
                self.assertEqual(rec["outcome"], "ok", arm)
                self.assertEqual(rec["exit_code"], 0, arm)
                self.assertTrue(rec["argv"], arm)
                self.assertIsNotNone(rec["arm_pid"], arm)
                # A real spawn costs orders of magnitude more than
                # an in-process dictionary write.
                self.assertGreater(rec["elapsed_ms"], 0.1, arm)

    def test_floor_agreement_when_the_floor_medians_are_close(self):
        recs = [measured("floor-direct", 50.9, kind="control"),
                measured("floor-spawn", 52.5, kind="control")]
        floor, agreed = report_mod.floor_ms(recs, "NO_WINDOW")
        self.assertTrue(agreed)
        self.assertEqual(floor, 52.5)

    def test_sleeper_floor_arm_breaks_agreement_and_suppresses_distance(self):
        recs = [measured("floor-direct", 51.0, kind="control"),
                measured("floor-spawn", 5000.0, kind="control"),
                measured("guard", 62.0)]
        _floor, agreed = report_mod.floor_ms(recs, "NO_WINDOW")
        self.assertFalse(agreed)
        decomp = report_mod.decompose(recs, pricing=None, context="NO_WINDOW")
        self.assertIn("status", decomp)
        self.assertNotIn("distance_above_floor_ms", decomp)
        text = report_mod.render(recs, FULL_COUNTS, {"guard": {}})
        self.assertNotIn("distance above floor:", text)


class KillTreeTests(unittest.TestCase):
    """The kill child is a tree; the shipped probe, handed the
    slot's recorded grandchild PID, decides survival per slot."""

    def test_direct_only_arm_leaves_descendant_survived(self):
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp, kill_mode="arm-kill")
            config["_windows_slot_jobs"] = sys.platform == "win32"
            from plan import Slot
            rec = run_slot(Slot("measured", "nuewframe", "kill",
                                "NO_WINDOW", 0), config)
            try:
                self.assertEqual(rec["outcome"], "descendant-survived")
                self.assertTrue(rec["survivor"])
                self.assertIsInstance(rec["grandchild_pid"], int)
                self.assertIsInstance(rec["child_pid"], int)
                self.assertEqual(rec["exit_code"], 124)
            finally:
                if sys.platform != "win32" and isinstance(rec.get("grandchild_pid"), int):
                    try:
                        os.kill(rec["grandchild_pid"], signal.SIGKILL)
                    except OSError:
                        pass

    def test_tree_killing_arm_leaves_no_survivor(self):
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            from plan import Slot
            rec = run_slot(Slot("measured", "guard", "kill",
                                "NO_WINDOW", 0), config)
            self.assertEqual(rec["outcome"], "ok")
            self.assertFalse(rec["survivor"])
            self.assertIsInstance(rec["grandchild_pid"], int)
            self.assertIsInstance(rec["child_pid"], int)
            self.assertEqual(rec["exit_code"], 124)

    def test_survivor_with_wrong_exit_is_classified_by_survival(self):
        # Survivor-before-exit precedence, exercised end to end:
        # an arm that kills only the direct child (the grandchild
        # survives) and returns exit code 7 instead of the
        # expected 124 is classified "descendant-survived" by the
        # runner — and the report names no inconsistency for the
        # record the runner itself produced, listing the exit
        # fault separately instead.
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp, kill_mode="arm-kill")
            arm_py = os.path.join(tmp, "arm-wrong-exit.py")
            with open(arm_py, "w", encoding="utf-8") as handle:
                handle.write(
                    "import subprocess, sys\n"
                    "timeout = float(sys.argv[2])\n"
                    "child = sys.argv[4:]\n"
                    "proc = subprocess.Popen(child)\n"
                    "try:\n"
                    "    proc.wait(timeout=timeout)\n"
                    "except subprocess.TimeoutExpired:\n"
                    "    proc.kill(); proc.wait()\n"
                    "sys.exit(7)\n")
            config["_windows_slot_jobs"] = sys.platform == "win32"
            config["arms"]["guard"]["templates"]["kill"][0] = arm_py
            from plan import Slot
            rec = run_slot(Slot("measured", "guard", "kill",
                                "NO_WINDOW", 0), config)
            try:
                self.assertEqual(rec["outcome"], "descendant-survived")
                self.assertTrue(rec["survivor"])
                self.assertEqual(rec["exit_code"], 7)
                self.assertEqual(
                    report_mod.record_consistency_losses([rec]), [])
                losses = report_mod.standing_losses([rec], FULL_COUNTS)
                self.assertTrue(any(
                    "exit mismatch" in loss
                    and "descendant-survived" in loss
                    for loss in losses), losses)
            finally:
                if sys.platform != "win32" and isinstance(rec.get("grandchild_pid"), int):
                    try:
                        os.kill(rec["grandchild_pid"], signal.SIGKILL)
                    except OSError:
                        pass

    def test_missing_probe_is_infra_failure_never_ok(self):
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            config["survivor_checker"] = None
            from plan import Slot
            rec = run_slot(Slot("measured", "guard", "kill",
                                "NO_WINDOW", 0), config)
            self.assertEqual(rec["outcome"], "infra-failure")
            self.assertIsNone(rec["survivor"])
            self.assertIn("probe", rec["detail"])

    def test_probe_answers_for_the_named_pids_only(self):
        live = subprocess.run([sys.executable, PROBE, str(os.getpid())],
                              capture_output=True, timeout=30)
        self.assertEqual(live.returncode, 1)
        child = subprocess.Popen([sys.executable, STUB, "exit0"])
        child.wait(timeout=30)
        dead = subprocess.run([sys.executable, PROBE, str(child.pid)],
                              capture_output=True, timeout=30)
        self.assertEqual(dead.returncode, 0)
        no_args = subprocess.run([sys.executable, PROBE],
                                 capture_output=True, timeout=30)
        self.assertEqual(no_args.returncode, 2)


class PerContextTests(unittest.TestCase):
    """Floor, distance, decomposition and medians are per context;
    no pooled number across contexts exists."""

    def two_context_records(self):
        recs = []
        for context in plan_mod.CONTEXTS:
            recs.append(measured("floor-direct", 40.0, kind="control",
                                 context=context))
            recs.append(measured("floor-spawn", 41.0, kind="control",
                                 context=context))
        recs.append(measured("guard", 50.0, context="NO_WINDOW"))
        recs.append(measured("guard", 150.0, context="DETACHED"))
        return recs

    def test_context_medians_are_never_pooled(self):
        recs = self.two_context_records()
        self.assertEqual(
            report_mod._median(recs, "guard", "fast", "NO_WINDOW"), 50.0)
        self.assertEqual(
            report_mod._median(recs, "guard", "fast", "DETACHED"), 150.0)
        near = report_mod.decompose(recs, pricing=None, context="NO_WINDOW")
        far = report_mod.decompose(recs, pricing=None, context="DETACHED")
        self.assertEqual(near["distance_above_floor_ms"], 9.0)
        self.assertEqual(far["distance_above_floor_ms"], 109.0)
        text = report_mod.render(recs, FULL_COUNTS, {"guard": {}})
        self.assertIn("[NO_WINDOW]", text)
        self.assertIn("[DETACHED]", text)
        self.assertNotIn("100.000", text)  # the pooled median of 50/150

    def test_absent_context_produces_no_number(self):
        recs = [r for r in complete_records()
                if r["context"] == "NO_WINDOW"]
        floor, agreed = report_mod.floor_ms(recs, "DETACHED")
        self.assertIsNone(floor)
        self.assertFalse(agreed)
        decomp = report_mod.decompose(recs, pricing=None, context="DETACHED")
        self.assertIn("status", decomp)
        self.assertNotIn("distance_above_floor_ms", decomp)
        losses = report_mod.standing_losses(recs, FULL_COUNTS)
        self.assertTrue(any("DETACHED" in loss for loss in losses))


class SlotAccountingTests(unittest.TestCase):
    """Completeness is exact per-cell accounting against the plan,
    and exit codes are validated against the expected table."""

    def test_degenerate_fixture_names_the_missing_cells(self):
        recs = []
        for _rep in range(plan_mod.EXPECTED_MEASURED):
            recs.append(measured("guard", 62.0, rep=0))
        recs.append(measured("floor-direct", 51.0, kind="control"))
        recs.append(measured("floor-spawn", 50.5, kind="control"))
        losses = report_mod.standing_losses(recs, FULL_COUNTS)
        self.assertTrue(losses)
        self.assertTrue(any("missing" in loss and "processkit" in loss
                            for loss in losses))
        self.assertTrue(any("DETACHED" in loss for loss in losses))
        self.assertTrue(any("kill" in loss for loss in losses))

    def test_duplicate_swap_is_caught_at_constant_total(self):
        recs = complete_records()
        victim = next(r for r in recs
                      if r["arm"] == "processkit" and r["path"] == "kill"
                      and r["context"] == "DETACHED" and r["rep"] == 5)
        recs.remove(victim)
        source = next(r for r in recs
                      if r["arm"] == "guard" and r["path"] == "fast"
                      and r["context"] == "NO_WINDOW" and r["rep"] == 3)
        recs.append(dict(source))
        self.assertEqual(len(recs), plan_mod.EXPECTED_TOTAL)  # total unchanged
        losses = report_mod.standing_losses(recs, FULL_COUNTS)
        self.assertTrue(any("duplicate" in loss for loss in losses))
        self.assertTrue(any("missing" in loss and "processkit" in loss
                            for loss in losses))

    def test_exit_mismatch_excluded_from_medians_and_listed(self):
        recs = [measured("guard", 60.0, rep=0),
                measured("guard", 62.0, rep=1),
                measured("guard", 64.0, rep=2),
                measured("guard", 9999.0, rep=3, outcome="exit-mismatch",
                         exit_code=125,
                         detail="exit code 125 != expected 0 for guard/fast")]
        self.assertEqual(
            report_mod._median(recs, "guard", "fast", "NO_WINDOW"), 62.0)
        losses = report_mod.standing_losses(recs, FULL_COUNTS)
        self.assertTrue(any("exit mismatch" in loss for loss in losses))

    def test_stub_arm_exiting_125_on_fast_is_exit_mismatch(self):
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            config["arms"]["guard"]["templates"]["fast"] = [
                "-c", "raise SystemExit(125)"]
            from plan import Slot
            rec = run_slot(Slot("measured", "guard", "fast",
                                "NO_WINDOW", 0), config)
            self.assertEqual(rec["outcome"], "exit-mismatch")
            self.assertEqual(rec["exit_code"], 125)
            self.assertIn("expected 0", rec["detail"])


