def run_harness(tmp, config, out, *extra):
    cfg_path = os.path.join(tmp, "campaign.json")
    with open(cfg_path, "w", encoding="utf-8") as handle:
        json.dump(config, handle)
    done = subprocess.run(
        [sys.executable, os.path.join(CAMPAIGN, "harness.py"), "run",
         "--config", cfg_path, "--out", out] + list(extra),
        capture_output=True, text=True, timeout=300)
    return done, cfg_path


def hash_tree(root):
    import hashlib
    out = {}
    for dirpath, _dirs, files in os.walk(root):
        for name in files:
            path = os.path.join(dirpath, name)
            with open(path, "rb") as handle:
                out[os.path.relpath(path, root)] = hashlib.sha256(
                    handle.read()).hexdigest()
    return out


class EnvCaseHelperTests(unittest.TestCase):
    """The shared case-insensitive setting rule (envcase), pinned
    directly: variants collapse to the intended spelling, and a
    mapping with no pre-existing variant is unchanged apart from
    the new key (the negative control)."""

    def test_no_preexisting_variant_is_unchanged_apart_from_the_new_key(self):
        env = {"PTG_MARKER": "kept", "Other": "also-kept"}
        out = envcase.set_env_var(env, "PATH", "controlled")
        self.assertEqual(out, {"PTG_MARKER": "kept",
                               "Other": "also-kept",
                               "PATH": "controlled"})

    def test_variants_collapse_to_the_intended_spelling_and_value(self):
        env = {"pAtH": "old-a", "Path": "old-b", "Other": "kept"}
        out = envcase.set_env_var(env, "PATH", "controlled")
        self.assertEqual(envcase.matching_keys(out, "path"), ["PATH"])
        self.assertEqual(out["PATH"], "controlled")
        self.assertEqual(out["Other"], "kept")


class PricingProbeTests(unittest.TestCase):
    """The CO-7 pricing probes are campaign steps: the harness runs
    them, their raw observations are recorded, and prices reach the
    decomposition only as a reference to those records."""

    def test_probes_run_and_price_each_expensive_item(self):
        import pricing as pricing_mod
