    def parse_measurement_census(self, text):
        """Re-derive the census enumeration from MEASUREMENT.md
        section 2. Parsing method: sections 2.1 and 2.2 are
        sliced by their headings (to the next heading of the
        same or a higher level); each markdown table row is
        split on "|" into Step / Calls / Count cells (no cell
        contains a "|"); a named call is a backticked name
        followed by its integer multiplicity in the Calls cell;
        an em dash in the Calls cell means no calls; a sole
        backticked name with no multiplicity (the hook path's
        payload reads, stated there as per window fill) takes
        the row's Count-column figure; the Count column's
        leading integer is the row count, and the bold Total
        row is the path total. The run-core subtotal is the
        figure the prose sentence after the plain-path table
        states ("The subtotal from job setup to process exit
        is N"), over the plain steps from the Job setup row
        through the last row."""
        import re

        def parse_path(heading):
            lines = text.splitlines()
            start = next(i for i, line in enumerate(lines)
                         if line.startswith(heading))
            end = next(
                (i for i in range(start + 1, len(lines))
                 if lines[i].startswith("### ")
                 or lines[i].startswith("## ")),
                len(lines))
            steps = []
            total = None
            total_label = None
            for line in lines[start:end]:
                if not line.startswith("|"):
                    continue
                cells = [cell.strip() for cell in
                         line.strip().strip("|").split("|")]
                if len(cells) != 3:
                    continue
                step, calls_cell, count_cell = cells
                if step == "Step (source)" \
                        or set(step) <= set("-: "):
                    continue
                if step.startswith("**Total"):
                    total_label = step.strip("*")
                    total = int(re.search(r"\d+", count_cell).group())
                    continue
                count = int(re.search(r"\d+", count_cell).group())
                pairs = [(match.group(1), int(match.group(2)))
                         for match in re.finditer(
                             r"`([^`]+)`\s*(\d+)", calls_cell)]
                if pairs:
                    calls = pairs
                elif calls_cell == "—":
                    calls = []
                else:
                    names = re.findall(r"`([^`]+)`", calls_cell)
                    self.assertEqual(len(names), 1, calls_cell)
                    calls = [(names[0], count)]
                self.assertEqual(
                    sum(call_count for _name, call_count in calls),
                    count, step)
                steps.append({"step": step, "calls": calls,
                              "count": count})
            return {"section": lines[start].lstrip("# ").strip(),
                    "total_label": total_label, "steps": steps,
                    "total": total}

        parsed = {"hook_path": parse_path("### 2.1"),
                  "plain_path": parse_path("### 2.2")}
        match = re.search(
            r"The subtotal from job setup to process exit is (\d+)",
            text)
        self.assertIsNotNone(match)
        plain_steps = parsed["plain_path"]["steps"]
        first = next(i for i, step in enumerate(plain_steps)
                     if step["step"].startswith("Job setup"))
        parsed["subtotal_run_core"] = {
            "steps": [step["step"] for step in plain_steps[first:]],
            "total": int(match.group(1))}
        return parsed

    def census_shape(self, data):
        """A census enumeration (vendored or re-derived) reduced
        to the comparable shape: per path, its section, total
        label, ordered steps (step text, ordered (name, count)
        call pairs, row count) and total; plus the subtotal's
        ordered step list and total."""
        shape = {}
        for key in ("hook_path", "plain_path"):
            path = data[key]
            shape[key] = {
                "section": path["section"],
                "total_label": path["total_label"],
                "steps": [
                    {"step": step["step"],
                     "calls": [(call["name"], call["count"])
                               if isinstance(call, dict)
                               else tuple(call)
                               for call in step["calls"]],
                     "count": step["count"]}
                    for step in path["steps"]],
                "total": path["total"]}
        shape["subtotal_run_core"] = {
            "steps": list(data["subtotal_run_core"]["steps"]),
            "total": data["subtotal_run_core"]["total"]}
        return shape

