    def derived_skipped_count(self):
        """The execute/skip split this machine's run produces,
        derived from the suite's own gating: the test methods of
        every class the guard-presence decorator gates
        (needs_guard in the coverage, guard and scanner families),
        counted from the test sources by AST. On a machine with
        no built guard package those classes all skip; the one
        win32-gated method runs on Linux and the census
        re-derivation skips only when the tree is absent, so
        neither moves this machine's split."""
        import ast
        total = 0
        for name in sorted(os.listdir(HERE)):
            if not (name.startswith("test_") and name.endswith(".py")):
                continue
            with open(os.path.join(HERE, name), encoding="utf-8") as fh:
                module = ast.parse(fh.read())
            for node in module.body:
                if not isinstance(node, ast.ClassDef):
                    continue
                decorators = [ast.unparse(d) for d in node.decorator_list]
                if "needs_guard" in decorators:
                    total += sum(
                        1 for item in node.body
                        if isinstance(item, ast.FunctionDef)
                        and item.name.startswith("test_"))
        return total

    def test_recorded_split_matches_the_derived_split(self):
        # Round-22 adjudication P7: round 21 held the counted-once
        # total in evidence/test-run.txt and stopped at the split
        # printed beside it — the same file's skipped fields and
        # the documents' run/skipped split could all be wrong at
        # a constant total. The split is held now: the gated
        # count re-derives from the test sources (above), the
        # evidence file's run / skipped / failures / errors are
        # held to it and to the runner's total, and the split
        # each document states in prose is held the same way.
        import re
        # This derivation is this machine's: a built guard
        # package would un-skip the gated families and the
        # recorded evidence (a Linux run) would not describe it.
        sys.path.insert(0, HERE)
        import guard_driver as drv
        if drv.guard_present():
            self.skipTest(
                "guard binaries are built here; the recorded "
                "split is the no-guard Linux run's and the gated "
                "families execute on this machine")
        done = subprocess.run(
            [sys.executable,
             os.path.join(HERE, "..", "run_tests.py"), "--count-only"],
            capture_output=True, text=True, timeout=120)
        self.assertEqual(done.returncode, 0, done.stderr)
        total = int(done.stdout.strip())
        skipped = self.derived_skipped_count()
        self.assertGreater(skipped, 0)
        executed = total - skipped
        with open(os.path.join(HERE, "..", "evidence", "test-run.txt"),
                  encoding="utf-8") as handle:
            recorded = handle.read()
        match = re.search(r"OK \(skipped=(\d+)\)", recorded)
        self.assertIsNotNone(
            match, "evidence/test-run.txt records no skipped count")
        self.assertEqual(int(match.group(1)), skipped,
                         "evidence/test-run.txt skipped field is "
                         "stale against the derived gated count")
        match = re.search(
            r"counted-once total: (\d+) tests \((\d+) run, "
            r"(\d+) skipped, (\d+) failures, (\d+) errors\)", recorded)
        self.assertIsNotNone(
            match, "evidence/test-run.txt records no split line")
        self.assertEqual(
            [int(group) for group in match.groups()],
            [total, total, skipped, 0, 0],
            "evidence/test-run.txt split is stale against the "
            "runner's total and the derived gated count")
        with open(os.path.join(HERE, "..", "README.md"),
                  encoding="utf-8") as handle:
            readme = handle.read()
        match = re.search(
            r"\((\d+) execute\s+on any platform; (\d+) drive the guard",
            readme)
        self.assertIsNotNone(match, "README states no execute/skip split")
        self.assertEqual([int(match.group(1)), int(match.group(2))],
                         [executed, skipped],
                         "README's split is stale")
        with open(os.path.join(HERE, "..", "VERIFICATION.md"),
                  encoding="utf-8") as handle:
            verification = handle.read()
        match = re.search(
            r"(\d+) run and pass, (\d+) skipped .*?(\d+) failures, "
            r"(\d+) errors", verification, re.S)
        self.assertIsNotNone(
            match, "VERIFICATION item 1 states no split")
        self.assertEqual(
            [int(group) for group in match.groups()],
            [executed, skipped, 0, 0],
            "VERIFICATION item 1's split is stale")
        # Round-25 adjudication P6: VERIFICATION's theory
        # section restates the same split figure ("The 53
        # guard-driving tests") outside item 1's phrasing, in
        # no held set. It joins the held set here, against the
        # same derived skipped count.
        match = re.search(r"The (\d+) guard-driving tests",
                          verification)
        self.assertIsNotNone(
            match, "VERIFICATION's theory section states no "
                   "guard-driving count")
        self.assertEqual(int(match.group(1)), skipped,
                         "VERIFICATION theory section's "
                         "guard-driving count is stale")

    def test_verification_section4_prose_coordinates_match_the_fresh_battery_record(self):
        # Round-22 adjudication P6: round 21 held the battery
        # JSON record to a fresh run and re-recorded VERIFICATION
        # item 4's prose coordinates from it, but no test read the
        # prose copy — mutated prose coordinates passed every
        # census test while the JSON stayed fresh. The prose
        # coordinates join the held set now: every line number
        # item 4's prose states must be a coordinate the fresh
        # battery record itself states, and the four headline
        # coordinates (the Sleep(10) poll, vars_os, Console::finish
        # and CreateIoCompletionPort) must appear in the prose at
        # exactly the fresh record's lines.
        import re
        tree = os.path.normpath(os.path.join(HERE, "..", ".."))
        if not os.path.isdir(tree):
            self.skipTest(
                "guard tree not present at the suite's expected "
                f"relative location ({tree}); the fresh battery "
                "record cannot be re-derived here")
        battery_mod = battery_module()
        ctx = {"tree": tree, "platform": sys.platform, "driver_mode": "blocked"}
        fresh = [case.run(ctx) for case in battery_mod.CASES]
        fresh_lines = set()
        for report in fresh:
            for condition in report["conditions"]:
                fresh_lines.update(
                    int(n) for n in re.findall(
                        r"line (\d+)", condition.get("detail", "")))
        self.assertTrue(fresh_lines)
        with open(os.path.join(HERE, "..", "VERIFICATION.md"),
                  encoding="utf-8") as handle:
            text = handle.read()
        section = text.split("4. **Battery audit parts", 1)[1].split(
            "5. **Syntax", 1)[0]
        prose_lines = set()
        for group in re.findall(r"lines? ((?:\d+(?:, \d+)*))", section):
            prose_lines.update(int(n) for n in group.split(", "))
        self.assertTrue(prose_lines)
        self.assertLessEqual(
            prose_lines, fresh_lines,
            f"VERIFICATION item 4 prose states line(s) "
            f"{sorted(prose_lines - fresh_lines)} that the fresh "
            f"battery record does not state")
        # The headline coordinates, derived from the fresh
        # record's own details (case a's poll line, case l's
        # vars_os line, case n's Console::finish line, case o's
        # CreateIoCompletionPort line).
        details = {report["case"]: " ".join(
            condition.get("detail", "")
            for condition in report["conditions"]) for report in fresh}
        # The headline sentences in the fresh record: a's
        # "line N: Sleep(10)", l's "line N: environment_block
        # builds from vars_os", n's "Console::finish, line N",
        # o's "CreateIoCompletionPort at line N".
        expected_headlines = set()
        match = re.search(r"line (\d+): Sleep\(10\)", details["a"])
        self.assertIsNotNone(match)
        expected_headlines.add(int(match.group(1)))
        match = re.search(
            r"line (\d+): environment_block builds from vars_os",
            details["l"])
        self.assertIsNotNone(match)
        expected_headlines.add(int(match.group(1)))
        match = re.search(r"Console::finish, line (\d+)", details["n"])
        self.assertIsNotNone(match)
        expected_headlines.add(int(match.group(1)))
        match = re.search(r"CreateIoCompletionPort at line (\d+)",
                          details["o"])
        self.assertIsNotNone(match)
        expected_headlines.add(int(match.group(1)))
        self.assertLessEqual(
            expected_headlines, prose_lines,
            f"VERIFICATION item 4 prose does not state the fresh "
            f"record's headline coordinates "
            f"{sorted(expected_headlines - prose_lines)}")

    def test_verification_section4_prose_subjects_and_duration_match_the_fresh_record(self):
        # Round-23 adjudication P6: the §4 hold above reads bare
        # line numbers only — the prose could name a function
        # that does not contain its coordinate, a file that does
        # not exist, another consumer's line for a named
        # consumer, and a wrong 14,400 s figure, all at once,
        # with the test green. The prose claims join the hold
        # paired with their subjects: every (file, function,
        # line) the prose states must be a triple the fresh
        # battery record states for that function; every named
        # handle consumer with its line must be a consumer the
        # fresh case-(m) detail enumerates at that line; and
        # the case-(m) driver deadline figure must be the
        # battery's own driver_timeout_s for case (m), in the
        # prose's comma format.
        import re
        tree = os.path.normpath(os.path.join(HERE, "..", ".."))
        if not os.path.isdir(tree):
            self.skipTest(
                "guard tree not present at the suite's expected "
                f"relative location ({tree}); the fresh battery "
                "record cannot be re-derived here")
        battery_mod = battery_module()
        ctx = {"tree": tree, "platform": sys.platform, "driver_mode": "blocked"}
        fresh = [case.run(ctx) for case in battery_mod.CASES]
        details = {report["case"]: " ".join(
            condition.get("detail", "")
            for condition in report["conditions"]) for report in fresh}
        all_details = " ".join(details.values())
        fresh_triples = set(re.findall(
            r"(src/[\w/]+\.rs), function ([\w:]+), line (\d+)",
            all_details))
        fresh_triples = {(f, fn, int(n)) for f, fn, n in fresh_triples}
        self.assertTrue(fresh_triples)
        with open(os.path.join(HERE, "..", "VERIFICATION.md"),
                  encoding="utf-8") as handle:
            text = handle.read()
        section = text.split("4. **Battery audit parts", 1)[1].split(
            "5. **Syntax", 1)[0]
        section = re.sub(r"\s+", " ", section)
        # (file, function, line) triples in "`file`, function
        # `name`, line N" form.
        prose_triples = {(f, fn, int(n)) for f, fn, n in re.findall(
            r"`(src/[\w/]+\.rs)`, function `([\w:]+)`, line (\d+)",
            section)}
        self.assertTrue(prose_triples)
        self.assertLessEqual(
            prose_triples, fresh_triples,
            f"VERIFICATION item 4 prose states (file, function, "
            f"line) triple(s) {sorted(prose_triples - fresh_triples)} "
            f"the fresh battery record does not state for that "
            f"function")
        # Console::finish: "`Console::finish` at `file` line N".
        match = re.search(
            r"`Console::finish` at `(src/[\w/]+\.rs)` line (\d+)",
            section)
        self.assertIsNotNone(match, "item 4 states no Console::finish "
                                    "coordinate")
        self.assertIn((match.group(1), "Console::finish",
                       int(match.group(2))), fresh_triples)
        # CreateIoCompletionPort inside Extension::start at its line.
        match = re.search(
            r"`CreateIoCompletionPort` inside `Extension::start` "
            r"at `(src/[\w/]+\.rs)` line (\d+)", section)
        self.assertIsNotNone(match)
        self.assertIn(
            f"CreateIoCompletionPort at line {match.group(2)}",
            details["o"])
        self.assertEqual(match.group(1), "src/extend/server.rs")
        # The pseudo-handle fetch sites beside their functions:
        # harden_self (lines ...), watched_owner_handles (line N),
        # cli_exit (line N) in the fresh case-(m) detail.
        fresh_m = details["m"]
        site_lines = {}
        for _name, _file, fn, n in re.findall(
                r"([\w ]*?): (src/[\w/]+\.rs), function ([\w:]+), "
                r"line (\d+)", fresh_m):
            site_lines.setdefault(fn, set()).add(int(n))
        prose_sites = {}
        match = re.search(r"`harden_self` \(lines ([\d, ]+)\)", section)
        self.assertIsNotNone(match)
        prose_sites["harden_self"] = {
            int(n) for n in match.group(1).split(", ")}
        for fn in ("watched_owner_handles", "cli_exit"):
            match = re.search(rf"`{fn}` \(line (\d+)\)", section)
            self.assertIsNotNone(match, fn)
            prose_sites[fn] = {int(match.group(1))}
        for fn, lines in prose_sites.items():
            self.assertEqual(lines, site_lines.get(fn), fn)
        # Named handle consumers with their lines, held to the
        # consumers the fresh case-(m) detail enumerates.
        fresh_consumers = {(name, int(n)) for name, n in re.findall(
            r"(\w+) \(line (\d+)\)", fresh_m)}
        prose_consumers = {(name, int(n)) for name, n in re.findall(
            r"`(\w+)` line (\d+)", section)}
        self.assertTrue(prose_consumers)
        self.assertLessEqual(
            prose_consumers, fresh_consumers,
            f"VERIFICATION item 4 prose states consumer(s) "
            f"{sorted(prose_consumers - fresh_consumers)} the fresh "
            f"battery record does not enumerate at those lines")
        # The case-(m) driver deadline figure: the battery's own
        # driver_timeout_s for case (m), comma-formatted as the
        # prose states it.
        case_m = next(case for case in battery_mod.CASES
                      if case.ident == "m")
        match = re.search(
            r"driver deadline in battery\.py is ([\d,]+) s", section)
        self.assertIsNotNone(match, "item 4 states no case-(m) "
                                    "driver deadline figure")
        self.assertEqual(match.group(1),
                         f"{case_m.driver_timeout_s:,}")
        # Round-25 adjudication P6: the theory section's copy
        # of the same figure ("with the driver's 14,400 s
        # deadline") sits outside item 4's section slice and
        # was held nowhere. Every such restatement in the
        # document joins the held set here, against the same
        # battery record.
        theory_copies = re.findall(
            r"driver's ([\d,]+) s deadline", text)
        self.assertTrue(
            theory_copies, "VERIFICATION's theory section states "
                           "no case-(m) driver deadline copy")
        for stated in theory_copies:
            self.assertEqual(stated,
                             f"{case_m.driver_timeout_s:,}",
                             "VERIFICATION theory section's "
                             "case-(m) deadline copy is stale")

    def test_documents_scanner_and_campaign_figures_match_their_sources(self):
        # Round-23 adjudication P7: the documents' copies of held
        # quantities were held nowhere — README's and
        # FAILURE-TREE's scanner counts (the summary behind them
        # is recomputed by CorpusTests) and the campaign-size
        # figures (the plan behind them is held in code) could
        # contradict their sources in print with the suite
        # green. The copies join the census: scanner counts held
        # to evidence/scanner-corpus-summary.json's recorded
        # (and elsewhere recomputed) fields, campaign figures
        # held to check_plan(build_plan()).
        import re
        with open(os.path.join(HERE, "..", "evidence",
                               "scanner-corpus-summary.json"),
                  encoding="utf-8") as handle:
            summary = json.load(handle)
        counts = plan_mod.check_plan(plan_mod.build_plan())
        total = sum(counts.values())
        with open(os.path.join(HERE, "..", "README.md"),
                  encoding="utf-8") as handle:
            readme = re.sub(r"\s+", " ", handle.read())
        match = re.search(r"seeded corpus of (\d+) generated", readme)
        self.assertIsNotNone(match, "README states no corpus size")
        self.assertEqual(int(match.group(1)), summary["corpus_cases"])
        match = re.search(r"in ([\d,]+) comparisons per Windows",
                          readme)
        self.assertIsNotNone(match, "README states no comparison count")
        self.assertEqual(int(match.group(1).replace(",", "")),
                         summary["guard_side_comparisons_per_windows_run"])
        plan_statements = re.findall(
            r"as configured: ([\d,]+) slots — (\d+) control \+ "
            r"(\d+) warmup \+ ([\d,]+) measured", readme)
        self.assertTrue(plan_statements,
                        "README states no campaign decomposition")
        for stated in plan_statements:
            self.assertEqual(
                [int(part.replace(",", "")) for part in stated],
                [total, counts["control"], counts["warmup"],
                 counts["measured"]], stated)
        with open(os.path.join(HERE, "..", "FAILURE-TREE.md"),
                  encoding="utf-8") as handle:
            failure_tree = re.sub(r"\s+", " ", handle.read())
        match = re.search(r"seeded (\d+)-case corpus", failure_tree)
        self.assertIsNotNone(match)
        self.assertEqual(int(match.group(1)), summary["corpus_cases"])
        match = re.search(
            r"([\d,]+) guard-vs-reference comparisons", failure_tree)
        self.assertIsNotNone(match)
        self.assertEqual(int(match.group(1).replace(",", "")),
                         summary["guard_side_comparisons_per_windows_run"])
        match = re.search(
            r"(\d+) \+ (\d+) \+ (\d+) = (\d+)", failure_tree)
        self.assertIsNotNone(match, "FAILURE-TREE states no plan "
                                    "decomposition")
        self.assertEqual([int(group) for group in match.groups()],
                         [counts["control"], counts["warmup"],
                          counts["measured"], total])
        # Round-24 adjudication P7: VERIFICATION.md's own copies
        # of the same quantities were the one document the hold
        # stopped short of — its corpus sentence with the full
        # category breakdown and largest payload, its verdict
        # tallies, its two comparison counts and its two
        # campaign-size statements could each contradict the
        # same sources with the suite green. They join the held
        # set here, against the same independent sources.
        with open(os.path.join(HERE, "..", "VERIFICATION.md"),
                  encoding="utf-8") as handle:
            verification = re.sub(r"\s+", " ", handle.read())
        match = re.search(
            r"corpus of (\d+) cases \((\d+) directed, "
            r"(\d+) cursor-directed, (\d+) timeout-token, "
            r"(\d+) structure, (\d+) window-edge, (\d+) mutation, "
            r"(\d+) fuzz; largest payload ([\d,]+) bytes",
            verification)
        self.assertIsNotNone(match, "VERIFICATION item 7 states "
                                    "no corpus breakdown")
        categories = summary["categories"]
        window_edge = sum(
            count for name, count in categories.items()
            if name.startswith("window-"))
        self.assertEqual(
            [int(part.replace(",", ""))
             for part in match.groups()],
            [summary["corpus_cases"], categories["directed"],
             categories["directed-cursor"],
             categories["timeout-token"], categories["structure"],
             window_edge, categories["mutation"],
             categories["fuzz"], summary["max_payload_bytes"]],
            match.groups())
        match = re.search(
            r"full/pretooluse (\d+) allow / (\d+) deny; "
            r"gate/pretooluse (\d+) / (\d+); cursor (\d+) / "
            r"(\d+) under both roles", verification)
        self.assertIsNotNone(match, "VERIFICATION item 7 states "
                                    "no verdict tallies")
        layouts = summary["reference_verdicts_canonical_layout"]
        self.assertEqual(
            [int(group) for group in match.groups()],
            [layouts["full/pretooluse"]["allow"],
             layouts["full/pretooluse"]["deny"],
             layouts["gate/pretooluse"]["allow"],
             layouts["gate/pretooluse"]["deny"],
             layouts["full/cursor"]["allow"],
             layouts["full/cursor"]["deny"]], match.groups())
        self.assertEqual(layouts["gate/cursor"],
                         layouts["full/cursor"])
        comparisons = re.findall(
            r"([\d,]+) (?:verdict )?comparisons", verification)
        self.assertGreaterEqual(
            len(comparisons), 2,
            "VERIFICATION states its comparison count in fewer "
            "than the two places it restates it")
        for stated in comparisons:
            self.assertEqual(
                int(stated.replace(",", "")),
                summary["guard_side_comparisons_per_windows_run"],
                stated)
        for stated in re.findall(r"([\d,]+)-case", verification):
            self.assertEqual(
                int(stated.replace(",", "")),
                summary["corpus_cases"], stated)
        match = re.search(
            r"([\d,]+) records as configured", verification)
        self.assertIsNotNone(match, "VERIFICATION item 6 states "
                                    "no campaign size")
        self.assertEqual(int(match.group(1).replace(",", "")), total)
        match = re.search(
            r"([\d,]+) slots — (\d+) control \+ (\d+) warmup \+ "
            r"([\d,]+) measured", verification)
        self.assertIsNotNone(match, "VERIFICATION's theory section "
                                    "states no campaign decomposition")
        self.assertEqual(
            [int(part.replace(",", "")) for part in match.groups()],
            [total, counts["control"], counts["warmup"],
             counts["measured"]], match.groups())

    def test_verification_item3_figures_match_the_preserved_reduced_package(self):
        # Round-23 adjudication P8: VERIFICATION item 3's prose
        # restates the preserved reduced-run package's figures
        # (standing losses, the floor medians, the pricing
        # medians) and no test read a single one — the package
        # is held in full, its prose copy was held nowhere. The
        # figures join the census, recomputed from the package's
        # own records: the outcome over its observations and
        # verified pricing, the floor arms' control medians per
        # context, and the pricing items' medians in PROBES
        # order, each compared in the prose's one-decimal form.
        import harness as harness_mod
        import pricing as pricing_mod
        import re
        package = os.path.join(HERE, "..", "evidence", "reduced-run")
        with open(os.path.join(package, "run.json"),
                  encoding="utf-8") as handle:
            meta = json.load(handle)
        records = harness_mod._read_records(package)
        probe_records = harness_mod._read_pricing_records(package)
        # Round-24 P5: the preserved package's one unverifiable
        # field is named, not silently passed — its recorded
        # config_templates cannot be checked against the run's
        # configuration because the package carries neither the
        # configuration's content nor a live anchor for it.
        package_problems = harness_mod.check_run_package(package)
        # Round-25 P1: the naming is general — the genuine
        # package's problems are exactly the degraded set its
        # absent anchor names unverifiable.
        assert_degraded_unverifiable_set(self, package_problems)
        evidence, problems = harness_mod._verified_pricing_evidence(
            meta, probe_records)
        self.assertIsNotNone(evidence, problems)
        outcome = harness_mod.campaign_outcome(
            records, meta["plan_counts"],
            pricing=evidence,
            decisions=harness_mod._recorded_decisions(meta),
            reduced=True,
            # Round-36 F3 construction truth: the recomputation
            # stands on the package checker's own footing —
            # the plan the package's anchored configuration
            # supplies (_package_plan_config), never the
            # shipped campaign's plan by default: this stub
            # run's genuine vectors are built from the stub
            # plan, and its absent anchor derives no budget.
            config=harness_mod._package_plan_config(meta))
        with open(os.path.join(HERE, "..", "VERIFICATION.md"),
                  encoding="utf-8") as handle:
            text = handle.read()
        section = text.split("3. **Reduced harness run**", 1)[1].split(
            "4. **Battery audit parts", 1)[0]
        section = re.sub(r"\s+", " ", section)
        match = re.search(r"(\d+) standing losses", section)
        self.assertIsNotNone(match, "item 3 states no standing-loss "
                                    "count")
        self.assertEqual(int(match.group(1)),
                         outcome["standing_loss_count"])
        self.assertEqual(int(match.group(1)),
                         meta["standing_loss_count"])

        def floor_medians(context):
            values = []
            for arm in ("floor-direct", "floor-spawn"):
                values.append(report_mod._median(
                    records, arm, "fast", context, kind="control"))
            return values

        for context in ("NO_WINDOW", "DETACHED"):
            # The verb the prose must carry is the package's own
            # floor verdict for the context (round-27: derived
            # from the package, not pinned to one preserved
            # run's load-shaped outcome — the medians beside it
            # are recomputed and compared exactly, as before).
            _floor, agreed = report_mod.floor_ms(records, context)
            verb = "agrees" if agreed else "disagrees"
            match = re.search(
                rf"{context} (?:floor )?pair {verb}.*?"
                rf"(?:medians |\()(-?[\d.]+) ms and (-?[\d.]+) ms",
                section, re.S)
            self.assertIsNotNone(
                match, f"item 3 states no {context} floor medians")
            expected = [f"{value:.1f}" for value in floor_medians(context)]
            self.assertEqual([match.group(1), match.group(2)], expected,
                             context)
        match = re.search(
            r"stub-tier medians (-?[\d.]+) ms, (-?[\d.]+) ms and "
            r"(-?[\d.]+) ms", section)
        self.assertIsNotNone(match, "item 3 states no pricing medians")
        expected = []
        for probe in pricing_mod.PROBES:
            item = pricing_mod.PROBES[probe]
            expected.append(f"{evidence['items'][item]['ms']:.1f}")
        self.assertEqual(list(match.groups()), expected)
        # Round-24 adjudication P9: the beside-figures in the
        # same paragraphs — the recorded seed, the slot count,
        # the paired-observation count and the freeze-gate
        # outcome — are produced by this same recomputation
        # (the manifest, the pricing evidence's record count
        # and the outcome above) and join the hold.
        match = re.search(r"records seed (\d+)", section)
        self.assertIsNotNone(match, "item 3 states no recorded seed")
        self.assertEqual(int(match.group(1)), meta["seed"])
        match = re.search(r"the (\d+)-slot execution order", section)
        self.assertIsNotNone(match, "item 3 states no slot count")
        self.assertEqual(int(match.group(1)), meta["slots_run"])
        self.assertEqual(int(match.group(1)), len(meta["order"]))
        match = re.search(
            r"executed all (\d+) paired stub-tier observations",
            section)
        self.assertIsNotNone(match, "item 3 states no paired "
                                    "observation count")
        self.assertEqual(int(match.group(1)), len(probe_records))
        self.assertEqual(int(match.group(1)),
                         meta["pricing_probe_observations"])
        self.assertEqual(outcome["freeze_gate_fail_count"],
                         meta["freeze_gate_fail_count"])
        if outcome["freeze_gate_fail_count"] == 0:
            self.assertIn("no freeze-gate FAIL", section)
        else:
            match = re.search(
                r"(\d+) freeze-gate FAIL", section)
            self.assertIsNotNone(match, "item 3 states no "
                                        "freeze-gate FAIL count")
            self.assertEqual(int(match.group(1)),
                             outcome["freeze_gate_fail_count"])
        # Round-24 adjudication P5: item 3's package-checker
        # sentence states the hold at its true breadth — the
        # preserved package's config_templates content is the
        # one field the checker cannot verify from the package
        # (its configuration anchor is absent), so the checker
        # names exactly that unverifiable field for this
        # package, and the prose says so (see the assertion on
        # check_run_package in Round24NeighbourTests).
        self.assertIn("config_templates", section)
        self.assertIn("unverifiable", section)

