    def test_shipped_kill_shape_without_child_pid_completes(self):
        # The shipped campaign's kill records as the runner writes
        # them on the Windows laptop: the workload is testkit
        # "spawn" running testkit "mark" — mark records the
        # grandchild's PID at the slot's marker and spawn records
        # no PID of its own, so every kill record's child_pid is
        # null while its grandchild_pid is recorded and its
        # survivor verdict rests on the probe of that PID. A
        # perfect campaign in that shape must complete: before
        # this control, the consistency discipline demanded both
        # PIDs, so the shipped shape earned 792 inconsistency
        # losses and kill-path correctness FAILed in both
        # contexts however well the guard killed.
        recs = complete_records()
        for record in recs:
            if record["path"] == "kill":
                record["child_pid"] = None
        self.assertEqual(report_mod.record_consistency_losses(recs), [])
        outcome = self.outcome(recs)
        self.assertEqual(outcome["campaign_status"], "complete")
        self.assertEqual(outcome["standing_loss_count"], 0)
        for context in plan_mod.CONTEXTS:
            entry = gate_entry(recs, "kill-path correctness", context)
            self.assertEqual(entry["outcome"], "PASS", context)

    def test_survivor_precedence_record_is_not_an_inconsistency(self):
        # A returned kill arm that left a survivor AND returned
        # the wrong exit code: the runner classifies by survival
        # (survivor-before-exit precedence), so the record is
        # truthful under its one label — the report must not call
        # it inconsistent, and must list the exit fault separately
        # under its own name, for the guard as a campaign loss.
        rec = measured("guard", 2100.0, path="kill",
                       outcome="descendant-survived", exit_code=7)
        rec["survivor"] = True
        self.assertEqual(report_mod.record_consistency_losses([rec]), [])
        losses = report_mod.standing_losses([rec], FULL_COUNTS)
        self.assertTrue(any(
            "guard kill path left a descendant alive" in loss
            for loss in losses), losses)
        self.assertTrue(any(
            "exit mismatch" in loss and "descendant-survived" in loss
            for loss in losses), losses)
        # The competitor form is competitor-loss evidence on both
        # components, minting no campaign standing loss of either.
        rec = measured("nuewframe", 2100.0, path="kill",
                       outcome="descendant-survived", exit_code=7)
        rec["survivor"] = True
        self.assertEqual(report_mod.record_consistency_losses([rec]), [])
        entries = report_mod.competitor_losses([rec])
        self.assertEqual(len(entries), 2, entries)
        losses = report_mod.campaign_losses([rec], FULL_COUNTS)
        campaign = [loss for loss in losses
                    if not loss.startswith(
                        report_mod.COMPETITOR_LOSS_PREFIX)]
        self.assertFalse(any("exit mismatch" in loss
                             for loss in campaign), campaign)

    def test_output_match_false_on_ok_guard_fast_record_is_a_named_loss(self):
        # The negative direction for the output fields: a guard
        # fast record classified "ok" whose own stdout verdict is
        # False claims a success its output observation refutes.
        # Before this control the gate's output dimension read
        # only the classification, so this record PASSed it and
        # the campaign completed.
        recs = complete_records()
        victim = next(r for r in recs
                      if r["arm"] == "guard" and r["path"] == "fast"
                      and r["kind"] == "measured"
                      and r["context"] == "NO_WINDOW")
        victim["output_stdout_match"] = False
        losses = self.inconsistency_losses(recs)
        self.assertTrue(any(
            "output_stdout_match is False" in loss
            and "guard/fast" in loss for loss in losses), losses)
        self.assertEqual(self.outcome(recs)["campaign_status"],
                         "incomplete")
        entry = gate_entry(recs, "output correctness", "NO_WINDOW")
        self.assertEqual(entry["outcome"], "FAIL")
        other = gate_entry(recs, "output correctness", "DETACHED")
        self.assertEqual(other["outcome"], "PASS")

    def test_descendant_label_without_survivor_evidence_mints_nothing(self):
        # A competitor's measured kill records relabelled
        # "descendant-survived" while their survivor fields say
        # False (no descendant was observed alive) must not mint
        # competitor-loss evidence, must not exclude the arm from
        # the kill-latency comparison, and must not let the
        # campaign complete — even when the arm's honest "ok"
        # times would have beaten the guard's, which is exactly
        # the loss the exclusion would have erased.
        recs = complete_records()
        for record in recs:
            if record["arm"] == "nuewframe" and record["path"] == "kill":
                record["elapsed_ms"] = 1000.0
        self.assertEqual(self.outcome(recs)["campaign_status"],
                         "incomplete")
        for record in recs:
            if record["arm"] == "nuewframe" and record["path"] == "kill" \
                    and record["kind"] == "measured":
                record["outcome"] = "descendant-survived"
                record["survivor"] = False
        self.assertEqual(report_mod.competitor_losses(recs), [])
        losses = self.inconsistency_losses(recs)
        self.assertTrue(any(
            "survivor is False" in loss and "nuewframe/kill" in loss
            for loss in losses), losses)
        self.assertEqual(self.outcome(recs)["campaign_status"],
                         "incomplete")
        for context in plan_mod.CONTEXTS:
            latency = gate_entry(recs, "kill-path latency", context)
            self.assertEqual(latency["outcome"], "UNEVALUATED", context)
            correctness = gate_entry(
                recs, "kill-path correctness", context)
            self.assertEqual(correctness["outcome"], "UNEVALUATED",
                             context)

    def test_survived_records_without_pid_form_identity_mint_nothing_and_are_named(self):
        # Round-20 adjudication P1: the PID-range discipline
        # (round-19 P2) stopped at outcome "ok" — a
        # "descendant-survived" record was earned from the
        # outcome label plus survivor True alone, never
        # consulting identity, so nuewframe's measured kill
        # records reclassified descendant-survived with
        # grandchild_pid -1 / null / missing / 10**30 (or both
        # PIDs absent — a shape no run can produce: with no
        # recorded PID the probe is never invoked and cannot
        # have answered True) minted competitor losses, were
        # excluded from the kill-latency comparison (erasing an
        # honest latency FAIL — their times are set FASTER than
        # the guard's below), and completed the campaign. A
        # survival is now earned only with a PID-form identity,
        # in the round-19 MAX_PID hold, and a survived record
        # carrying none is named as a record inconsistency.
        def bogus_records(mutate):
            recs = complete_records()
            for record in recs:
                if record["arm"] == "nuewframe" \
                        and record["path"] == "kill":
                    record["elapsed_ms"] = 1000.0
                    if record["kind"] == "measured":
                        record["outcome"] = "descendant-survived"
                        record["survivor"] = True
                        mutate(record)
            return recs

        # Genuine-PID control: the intended shape is unchanged
        # — every measured survival is competitor-loss
        # evidence, the arm is excluded from kill latency, and
        # the campaign completes.
        control = bogus_records(lambda r: None)
        survived_count = sum(
            1 for r in control if r["arm"] == "nuewframe"
            and r["path"] == "kill" and r["kind"] == "measured")
        self.assertGreater(survived_count, 0)
        self.assertEqual(len(report_mod.competitor_losses(control)),
                         survived_count)
        self.assertEqual(report_mod.record_consistency_losses(
            control), [])
        self.assertEqual(self.outcome(control)["campaign_status"],
                         "complete")
        for context in plan_mod.CONTEXTS:
            entry = gate_entry(control, "kill-path latency", context)
            self.assertEqual(entry["outcome"], "PASS", context)
        cases = [
            ("grandchild_pid -1",
             lambda r: r.update(grandchild_pid=-1),
             "grandchild_pid is -1"),
            ("grandchild_pid null",
             lambda r: r.update(grandchild_pid=None),
             "grandchild_pid is missing or null"),
            ("grandchild_pid missing",
             lambda r: r.pop("grandchild_pid", None),
             "grandchild_pid is missing or null"),
            ("grandchild_pid 10**30",
             lambda r: r.update(grandchild_pid=10 ** 30),
             f"grandchild_pid is {10 ** 30}"),
            ("child_pid -5 with grandchild_pid -1",
             lambda r: r.update(child_pid=-5, grandchild_pid=-1),
             "child_pid is -5"),
            ("both identities null",
             lambda r: r.update(child_pid=None, grandchild_pid=None),
             "grandchild_pid is missing or null"),
            ("both identities missing",
             lambda r: (r.pop("child_pid", None),
                        r.pop("grandchild_pid", None)),
             "grandchild_pid is missing or null"),
        ]
        for label, mutate, needle in cases:
            recs = bogus_records(mutate)
            self.assertEqual(report_mod.competitor_losses(recs),
                             [], label)
            losses = self.inconsistency_losses(recs)
            self.assertTrue(any(
                needle in loss and "nuewframe/kill" in loss
                for loss in losses), (label, losses[:2]))
            self.assertEqual(self.outcome(recs)["campaign_status"],
                             "incomplete", label)
            for context in plan_mod.CONTEXTS:
                entry = gate_entry(recs, "kill-path latency",
                                   context)
                self.assertEqual(entry["outcome"], "UNEVALUATED",
                                 (label, context))

