    def test_non_integer_exit_code_on_a_competitor_record_mints_nothing_and_is_named(self):
        # Round-20 adjudication P4: _evidenced_exit_mismatch
        # held an exit code to no type at all — actual !=
        # expected was the whole test — so one sysprims
        # measured fast record reclassified exit-mismatch with
        # exit_code "boom" (or 7.5, or True, or [7]) minted a
        # competitor-loss entry in a complete campaign, though
        # the runner records an integer exit code or none and
        # no instrument recorded such a fault. The fault is now
        # earned only from a non-boolean integer code, and a
        # non-integer code on the record is named as a record
        # inconsistency in the equal-value case's shape.
        def mutated(code):
            recs = complete_records()
            victim = next(
                r for r in recs if r["arm"] == "sysprims"
                and r["path"] == "fast" and r["kind"] == "measured")
            victim["outcome"] = "exit-mismatch"
            victim["exit_code"] = code
            return recs

        # Integer control: exactly one competitor-loss entry,
        # and the campaign still completes — the intended
        # shape is unchanged.
        control = mutated(7)
        entries = [e for e in report_mod.competitor_losses(control)
                   if "sysprims" in e]
        self.assertEqual(len(entries), 1, entries)
        self.assertEqual(report_mod.record_consistency_losses(
            control), [])
        self.assertEqual(self.outcome(control)["campaign_status"],
                         "complete")
        for code in ("boom", 7.5, True, [7]):
            recs = mutated(code)
            self.assertEqual(report_mod.competitor_losses(recs),
                             [], code)
            losses = self.inconsistency_losses(recs)
            self.assertTrue(any(
                f"exit_code is {code!r}" in loss
                and "not the integer exit code" in loss
                and "sysprims/fast" in loss for loss in losses),
                (code, losses[:2]))
            self.assertEqual(self.outcome(recs)["campaign_status"],
                             "incomplete", code)

