    def test_cmd_report_refuses_manifest_fields_in_wrong_shapes(self):
        # Round-18: cmd_report validated only that the manifest
        # is an object (and the records' shapes); the manifest
        # fields the render itself indexes — plan_counts,
        # fingerprints (and each fingerprint entry), platform,
        # arm_versions, order — were consumed unvalidated, so a
        # manifest missing one or carrying it in another shape
        # raised KeyError / AttributeError / TypeError out of
        # the render while check_run_package named nothing.
        import harness as harness_mod
        from types import SimpleNamespace

        def mutate_plan_counts(meta):
            meta.pop("plan_counts")

        def mutate_fingerprints_type(meta):
            meta["fingerprints"] = "not-an-object"

        def mutate_fingerprint_entry(meta):
            meta["fingerprints"] = {"guard": "not-an-object"}

        def mutate_platform(meta):
            meta.pop("platform")

        def mutate_arm_versions(meta):
            meta["arm_versions"] = ["not", "an", "object"]

        def mutate_order(meta):
            meta["provisional"] = True
            meta["order"] = 123

        for mutate, field in (
                (mutate_plan_counts, "plan_counts"),
                (mutate_fingerprints_type, "fingerprints"),
                (mutate_fingerprint_entry, "fingerprints.guard"),
                (mutate_platform, "platform"),
                (mutate_arm_versions, "arm_versions"),
                (mutate_order, "order")):
            with tempfile.TemporaryDirectory() as tmp:
                ns = self.evidence_ns(tmp)
                path = os.path.join(ns, "run.json")
                with open(path, encoding="utf-8") as handle:
                    meta = json.load(handle)
                mutate(meta)
                with open(path, "w", encoding="utf-8") as handle:
                    json.dump(meta, handle, indent=2)
                with contextlib.redirect_stdout(io.StringIO()):
                    with self.assertRaises(SystemExit) as raised:
                        harness_mod.cmd_report(
                            SimpleNamespace(out=ns))
                self.assertIn(field, str(raised.exception),
                              field)

