    # P5 — exit-code presence on survived records.
    def test_survived_records_without_an_exit_code_are_named_and_mint_nothing(self):
        import copy
        def mutated(exit_code):
            recs = copy.deepcopy(complete_records())
            count = 0
            for record in recs:
                if record["arm"] == "nuewframe" \
                        and record["path"] == "kill" \
                        and record["kind"] == "measured" \
                        and record["context"] == "NO_WINDOW":
                    record["outcome"] = "descendant-survived"
                    record["survivor"] = True
                    record["exit_code"] = exit_code
                    count += 1
            return recs, count
        recs, count = mutated(None)
        self.assertGreater(count, 0)
        inconsistencies = report_mod._record_inconsistencies(recs)
        named = [item for item in inconsistencies
                 if item["field"] == "exit_code"
                 and item["record"]["arm"] == "nuewframe"]
        self.assertEqual(len(named), count, inconsistencies[:3])
        self.assertEqual(report_mod.competitor_losses(recs), [])
        self.assertEqual(self.outcome(recs)["campaign_status"],
                         "incomplete")
        # The genuine control: the same survivals with the exit
        # code the runner records (124) are consistent and mint
        # their competitor losses exactly as before.
        control, control_count = mutated(124)
        self.assertEqual(control_count, count)
        self.assertEqual(report_mod._record_inconsistencies(control), [])
        self.assertEqual(len(report_mod.competitor_losses(control)),
                         count)

    # P6 — the context stamp hold on every probe pair.
    def test_owner_and_resolver_context_flips_are_stamp_defects_and_price_nothing(self):
        import pricing as pricing_mod
        diffs = {probe: [2.0] * 9 for probe in
                 ("console-probe-finish", "owner-verification",
                  "resolver-probe-count")}
        cases = [
            ("owner-verification", "baseline", "owner verification"),
            ("owner-verification", "loaded", "owner verification"),
            ("resolver-probe-count", "baseline",
             "resolver probe count"),
            ("resolver-probe-count", "loaded", "resolver probe count"),
        ]
        for probe, shape, item in cases:
            records = pricing_records(diffs)
            for record in records:
                if record["probe"] == probe \
                        and record["shape"] == shape:
                    record["context"] = "DETACHED"
            defects = pricing_mod.pricing_stamp_defects(records)
            self.assertIn(item, defects, (probe, shape))
            self.assertTrue(any(
                d["field"] == "context" for d in defects[item]),
                (probe, shape, defects))
            evidence = pricing_mod.prices_from_observations(records)
            self.assertIsNotNone(evidence, (probe, shape))
            self.assertNotIn(item, evidence["items"], (probe, shape))

