class Round22NeighbourTests(unittest.TestCase):
    """Round-22 adjudication: one step past round 21 — exit-code
    presence on every exit-derived classification, per-path field
    discipline, the config element/token level, the pricing stamp
    vector, and the expected_exit tables."""

    def shipped_decisions(self):
        cfg_path = os.path.join(HERE, "..", "campaign.json")
        with open(cfg_path, encoding="utf-8") as handle:
            config = json.load(handle)
        return report_mod.decisions_from_config(config)

    def outcome(self, records):
        import harness as harness_mod
        # Round-27 F2: this class's completeness premise carries
        # the manual usability check performed (dimension (8)
        # completes only on its artifact's recorded evidence).
        with collected_usability_artifact():
            return harness_mod.campaign_outcome(
                records, FULL_COUNTS, decisions=self.shipped_decisions())

    def write_payload(self, tmp, payload):
        path = os.path.join(tmp, "campaign.json")
        with open(path, "w", encoding="utf-8") as handle:
            json.dump(payload, handle)
        return path

    def mutate_one(self, records, arm, path, context="NO_WINDOW", rep=0):
        import copy
        recs = copy.deepcopy(records)
        for record in recs:
            if record["arm"] == arm and record["path"] == path \
                    and record["kind"] == "measured" \
                    and record["context"] == context \
                    and record["rep"] == rep:
                return recs, record
        raise AssertionError("fixture record not found")

    # P1 — exit-code presence on the output-mismatch label.
    def test_output_mismatch_without_an_observed_exit_code_is_named_and_mints_no_loss(self):
        recs, victim = self.mutate_one(
            complete_records(), "sysprims", "fast")
        victim["outcome"] = "output-mismatch"
        victim["output_stdout_match"] = False
        victim["exit_code"] = None
        inconsistencies = report_mod._record_inconsistencies(recs)
        self.assertTrue(any(
            item["record"] is victim and item["field"] == "exit_code"
            for item in inconsistencies), inconsistencies)
        self.assertEqual(report_mod.competitor_losses(recs), [])
        self.assertEqual(self.outcome(recs)["campaign_status"],
                         "incomplete")
        # The genuine control: the same label with the exit code
        # the runner records is consistent and mints its loss.
        control, victim = self.mutate_one(
            complete_records(), "sysprims", "fast")
        victim["outcome"] = "output-mismatch"
        victim["output_stdout_match"] = False
        victim["exit_code"] = 0
        self.assertEqual(report_mod._record_inconsistencies(control), [])
        self.assertEqual(len(report_mod.competitor_losses(control)), 1)
        self.assertEqual(self.outcome(control)["campaign_status"],
                         "complete")

    # P2 — per-path field discipline.
    def test_fast_record_carrying_a_survivor_value_is_named(self):
        for arm in ("guard", "sysprims"):
            recs, victim = self.mutate_one(complete_records(), arm, "fast")
            self.assertIsNone(victim["survivor"])
            victim["survivor"] = True
            inconsistencies = report_mod._record_inconsistencies(recs)
            self.assertTrue(any(
                item["record"] is victim and item["field"] == "survivor"
                for item in inconsistencies), (arm, inconsistencies))
            self.assertEqual(self.outcome(recs)["campaign_status"],
                             "incomplete", arm)

    def test_kill_record_carrying_output_fields_is_named(self):
        cases = [
            ("sysprims", {"output_stdout_match": False}),
            ("guard", {"output_stdout_match": False,
                       "output_stdout_sha256": "zzz",
                       "output_stdout_len": 99999}),
            ("guard", {"output_stderr_sha256": "a" * 64}),
        ]
        for arm, fields in cases:
            recs, victim = self.mutate_one(complete_records(), arm, "kill")
            for field, value in fields.items():
                self.assertIsNone(victim[field], (arm, field))
                victim[field] = value
            inconsistencies = report_mod._record_inconsistencies(recs)
            named = {item["field"] for item in inconsistencies
                     if item["record"] is victim}
            self.assertTrue(
                named & set(fields), (arm, fields, inconsistencies))
            self.assertEqual(self.outcome(recs)["campaign_status"],
                             "incomplete", (arm, fields))

