    # P3 — the pricing records' own classification and fields.
    def test_pricing_ok_record_with_contradicting_exit_code_prices_nothing(self):
        import harness as harness_mod
        import pricing as pricing_mod
        diffs = {probe: [2.0] * 9 for probe in
                 ("console-probe-finish", "owner-verification",
                  "resolver-probe-count")}
        records = pricing_records(diffs)
        for record in records:
            if record["probe"] == "owner-verification":
                record["exit_code"] = 999
        defects = pricing_mod.pricing_stamp_defects(records)
        self.assertIn("owner verification", defects)
        self.assertTrue(any(
            d["field"] == "exit_code" for d in defects["owner verification"]),
            defects)
        self.assertNotIn("console probe + console finish", defects)
        evidence = pricing_mod.prices_from_observations(records)
        self.assertIsNotNone(evidence)
        self.assertNotIn("owner verification", evidence["items"])
        self.assertIn("resolver probe count", evidence["items"])
        problems = harness_mod._pricing_shape_problems(records)
        self.assertTrue(any(
            "exit_code" in problem for problem in problems), problems)

