    # P11 — the preserved package's beside-fields.
    def preserved_package_copy(self, tmp):
        import shutil
        src = os.path.join(HERE, "..", "evidence", "reduced-run")
        # The copy keeps the package's namespace name (round-24:
        # the checker holds run_id to its namespace).
        pkg = os.path.join(tmp, "reduced-run")
        shutil.copytree(src, pkg)
        return pkg

    def test_package_checker_holds_run_id_environment_and_report_body(self):
        import harness as harness_mod
        with tempfile.TemporaryDirectory() as tmp:
            pkg = self.preserved_package_copy(tmp)
            # Genuine beside-fields check clean apart from
            # the degraded set round-25 P1 names unverifiable:
            # the preserved package's absent configuration
            # anchor degrades five verifications, each named
            # (round-37 F3: the argv length budget joined the
            # four round 25 named).
            control = harness_mod.check_run_package(pkg)
            assert_degraded_unverifiable_set(self, control)
            meta_path = os.path.join(pkg, "run.json")
            with open(meta_path, encoding="utf-8") as handle:
                meta = json.load(handle)
            meta["run_id"] = "run-19990101T000000Z-s1"
            meta["environment"]["platform"] = "Windows-11-fabricated"
            meta["environment"]["os"] = "Windows"
            with open(meta_path, "w", encoding="utf-8") as handle:
                json.dump(meta, handle, indent=2)
            report_path = os.path.join(pkg, "report.txt")
            with open(report_path, encoding="utf-8") as handle:
                text = handle.read()
            sha = meta["fingerprints"]["guard"]["sha256"]
            self.assertIn(sha, text)
            with open(report_path, "w", encoding="utf-8") as handle:
                handle.write(text.replace(sha, "f" * 64))
            problems = harness_mod.check_run_package(pkg)
            self.assertTrue(any(
                "run_id" in problem for problem in problems), problems)
            self.assertTrue(any(
                "environment" in problem for problem in problems),
                problems)
            self.assertTrue(any(
                "report.txt" in problem and "fingerprint" in problem
                for problem in problems), problems)

