    # P2 — the kill record's arm_pid completes the identity group.
    def test_kill_record_arm_pid_is_held_to_pid_form(self):
        # Out-of-range means outside the suite's PID form
        # (report.MAX_PID, 2**31 - 1): 999,999,999 is within
        # it and is a formally valid PID here, so the
        # out-of-range case is 9,999,999,999.
        for value in (None, -1, "not-a-pid", 9999999999, 4242.5):
            recs, victim = self.mutate_one(
                complete_records(), "guard", "kill")
            self.assertTrue(report_mod._is_pid_form(victim["arm_pid"]))
            victim["arm_pid"] = value
            inconsistencies = report_mod._record_inconsistencies(recs)
            self.assertTrue(any(
                item["record"] is victim
                and item["field"] == "arm_pid"
                for item in inconsistencies), (value, inconsistencies))
            self.assertEqual(self.outcome(recs)["campaign_status"],
                             "incomplete", value)
        # The genuine form passes unnamed.
        self.assertEqual(
            report_mod._record_inconsistencies(complete_records()), [])

    def test_survived_kill_record_arm_pid_is_held_and_mints_nothing(self):
        recs, victim = self.mutate_one(
            complete_records(), "nuewframe", "kill")
        victim["outcome"] = "descendant-survived"
        victim["survivor"] = True
        victim["arm_pid"] = None
        inconsistencies = report_mod._record_inconsistencies(recs)
        self.assertTrue(any(
            item["record"] is victim and item["field"] == "arm_pid"
            for item in inconsistencies), inconsistencies)
        self.assertFalse(report_mod._evidenced_survived(victim))
        self.assertEqual(report_mod.competitor_losses(recs), [])
        self.assertEqual(self.outcome(recs)["campaign_status"],
                         "incomplete")
        # The genuine control: the same survival with the arm
        # PID its slot writes is consistent and mints its loss.
        control, victim = self.mutate_one(
            complete_records(), "nuewframe", "kill")
        victim["outcome"] = "descendant-survived"
        victim["survivor"] = True
        self.assertEqual(report_mod._record_inconsistencies(control), [])
        self.assertEqual(len(report_mod.competitor_losses(control)), 1)

    # P3 — the owner-loaded records' bracket values.
    def test_owner_loaded_bracket_values_are_held(self):
        import harness as harness_mod
        import pricing as pricing_mod
        diffs = {probe: [2.0] * 9 for probe in
                 ("console-probe-finish", "owner-verification",
                  "resolver-probe-count")}
        control = pricing_records(diffs)
        self.assertEqual(pricing_mod.pricing_stamp_defects(control), {})
        self.assertEqual(harness_mod._pricing_shape_problems(control),
                         [])
        evidence = pricing_mod.prices_from_observations(control)
        self.assertIn("owner verification", evidence["items"])
        mutations = (
            ("guard_pid", None), ("guard_pid", -1),
            ("guard_pid", "not-a-pid"),
            ("outer_elapsed_ms", -5.0), ("outer_elapsed_ms", "soon"),
            ("outer_elapsed_ms", 0.001))
        for field, value in mutations:
            records = pricing_records(diffs)
            for record in records:
                if record["probe"] == "owner-verification" \
                        and record["shape"] == "loaded":
                    record[field] = value
            defects = pricing_mod.pricing_stamp_defects(records)
            self.assertIn("owner verification", defects,
                          (field, value))
            self.assertTrue(any(
                d["field"] == field
                for d in defects["owner verification"]),
                (field, value, defects))
            problems = harness_mod._pricing_shape_problems(records)
            self.assertTrue(any(
                field in problem for problem in problems),
                (field, value, problems))
            evidence = pricing_mod.prices_from_observations(records)
            self.assertIsNotNone(evidence, (field, value))
            self.assertNotIn("owner verification", evidence["items"],
                             (field, value))
            self.assertIn("resolver probe count", evidence["items"],
                          (field, value))

