class Round25NeighbourTests(unittest.TestCase):
    """Round-25 adjudication: the naming duty completed
    generally (P1), arm_pid / argv at the breadth the runner
    writes them (P2), the pricing records' fingerprint
    companions (P3), the environment hold made positional
    (P4), report.txt's verdict-bearing sections (P5), the
    documents' next-ring copies (P6), bare in-tree citations
    (P7), and the floor's quiet-condition qualification in
    VERIFICATION (P8)."""

    def preserved_package_copy(self, tmp):
        import shutil
        src = os.path.join(HERE, "..", "evidence", "reduced-run")
        pkg = os.path.join(tmp, "reduced-run")
        shutil.copytree(src, pkg)
        return pkg

    def load_meta(self, pkg):
        with open(os.path.join(pkg, "run.json"),
                  encoding="utf-8") as handle:
            return json.load(handle)

    def save_meta(self, pkg, meta):
        with open(os.path.join(pkg, "run.json"), "w",
                  encoding="utf-8") as handle:
            json.dump(meta, handle, indent=2)

    def shipped_decisions(self):
        cfg_path = os.path.join(HERE, "..", "campaign.json")
        with open(cfg_path, encoding="utf-8") as handle:
            config = json.load(handle)
        return report_mod.decisions_from_config(config)

    def outcome(self, records):
        import harness as harness_mod
        # Round-27 F2: this class's completeness premise carries
        # the manual usability check performed (dimension (8)
        # completes only on its artifact's recorded evidence).
        with collected_usability_artifact():
            return harness_mod.campaign_outcome(
                records, FULL_COUNTS, decisions=self.shipped_decisions())

    # P1 — the naming duty is general.
    def test_package_checker_names_the_full_degraded_set(self):
        import harness as harness_mod
        with tempfile.TemporaryDirectory() as tmp:
            pkg = self.preserved_package_copy(tmp)
            problems = harness_mod.check_run_package(pkg)
            assert_degraded_unverifiable_set(self, problems)
        # An anchored package names nothing unverifiable.
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            out = os.path.join(tmp, "results")
            done, _cfg = run_harness(tmp, config, out, "--reduced", "2")
            self.assertEqual(done.returncode, 0, done.stderr)
            ns = harness_mod.resolve_run_dir(out)
            self.assertEqual(harness_mod.check_run_package(ns), [])

    def test_fabrications_under_the_absent_anchor_are_named_unverifiable(self):
        import harness as harness_mod
        # Competitor identity fabricated (sha + version, the
        # report's arm line kept consistent): identity is
        # named unverifiable, and the problem set is exactly
        # the degraded set — the checker no longer compares
        # the package against its own recorded list.
        with tempfile.TemporaryDirectory() as tmp:
            pkg = self.preserved_package_copy(tmp)
            meta = self.load_meta(pkg)
            genuine_sha = meta["fingerprints"]["nuewframe"]["sha256"]
            meta["fingerprints"]["nuewframe"]["sha256"] = "f" * 64
            meta["arm_versions"]["nuewframe"] = "9.9.9-fabricated"
            self.save_meta(pkg, meta)
            report_path = os.path.join(pkg, "report.txt")
            with open(report_path, encoding="utf-8") as handle:
                lines = handle.read().splitlines(keepends=True)
            for i, line in enumerate(lines):
                if line.startswith("  nuewframe:"):
                    lines[i] = line.replace(genuine_sha, "f" * 64).replace(
                        "version=not probed", "version=9.9.9-fabricated")
            with open(report_path, "w", encoding="utf-8") as handle:
                handle.writelines(lines)
            problems = harness_mod.check_run_package(pkg)
            assert_degraded_unverifiable_set(self, problems)
        # A profile decision rewritten in every copy the
        # package carries: decisions are named unverifiable.
        # Round-26 alignment: the mapping's first entry is now
        # a collection declaration, not a decision; this
        # scenario's subject is a scope decision, so it takes
        # the first decided dimension. (A kind-flipping rewrite
        # of a collection declaration is the next scenario.)
        with tempfile.TemporaryDirectory() as tmp:
            pkg = self.preserved_package_copy(tmp)
            meta = self.load_meta(pkg)
            dim = next(
                dim for dim in meta["profile_dimension_decisions"]
                if report_mod.decision_reason(
                    dim, meta["profile_dimension_decisions"])
                is not None)
            old = meta["profile_dimension_decisions"][dim]
            fake = "Fabricated reason: decided away by edit."
            for name in ("run.json", "claim-ledger.json",
                         "report.txt"):
                path = os.path.join(pkg, name)
                with open(path, encoding="utf-8") as handle:
                    text = handle.read()
                # The rewrite rewrites each copy in the form
                # that file carries it (round-32 landing,
                # construction-truth): report.txt carries the
                # text raw; the JSON copies carry it as a JSON
                # string, escaped where the text is non-ASCII.
                # The scenario -- a decision rewritten in every
                # copy the package carries -- is unchanged, as
                # is its assertion (the degraded set, exactly).
                carried = old if old in text else \
                    json.dumps(old)[1:-1]
                self.assertIn(carried, text, name)
                with open(path, "w", encoding="utf-8") as handle:
                    handle.write(text.replace(carried, fake))
            problems = harness_mod.check_run_package(pkg)
            assert_degraded_unverifiable_set(self, problems)
        # A collection declaration (round-26) rewritten in
        # every copy the package carries: the rewrite flips
        # the entry's kind (a collection becomes a purported
        # decision), so beside the decisions-unverifiable
        # naming, the package's ledger and report — rendered
        # from the genuine declaration — disagree with the
        # recorded configuration they are recomputed against,
        # and those disagreements are named too; nothing about
        # the fabrication passes silently.
        with tempfile.TemporaryDirectory() as tmp:
            pkg = self.preserved_package_copy(tmp)
            meta = self.load_meta(pkg)
            dim = next(
                dim for dim in meta["profile_dimension_decisions"]
                if report_mod._collection_entry(
                    dim, meta["profile_dimension_decisions"])
                is not None)
            old = meta["profile_dimension_decisions"][dim]
            fake = "Fabricated reason: decided away by edit."
            for name in ("run.json", "claim-ledger.json",
                         "report.txt"):
                path = os.path.join(pkg, name)
                with open(path, encoding="utf-8") as handle:
                    text = handle.read()
                # The rewrite rewrites each copy in the form
                # that file carries it (round-32 landing,
                # construction-truth): report.txt carries the
                # text raw; the JSON copies carry it as a JSON
                # string, escaped where the text is non-ASCII.
                # The scenario -- a decision rewritten in every
                # copy the package carries -- is unchanged, as
                # is its assertion (the degraded set, exactly).
                carried = old if old in text else \
                    json.dumps(old)[1:-1]
                self.assertIn(carried, text, name)
                with open(path, "w", encoding="utf-8") as handle:
                    handle.write(text.replace(carried, fake))
            problems = harness_mod.check_run_package(pkg)
            self.assertTrue(any(
                "profile decisions are unverifiable" in problem
                for problem in problems), problems)
            self.assertTrue(any(
                "claim ledger" in problem
                for problem in problems), problems)
        # A True output verdict resting on other bytes: the
        # pairing's degradation is the one the naming covers —
        # the preserved package's anchor yields no expected
        # mapping, so the same fabricated record the genuine
        # mapping names is named nowhere at form level, while
        # the package checker names the pairing unverifiable.
        import hashlib
        with tempfile.TemporaryDirectory() as tmp:
            pkg = self.preserved_package_copy(tmp)
            meta = self.load_meta(pkg)
            self.assertIsNone(
                harness_mod._package_expected_output(meta))
            record = next(
                r for r in complete_records()
                if r["arm"] == "guard" and r["path"] == "fast"
                and r["kind"] == "measured")
            record["output_stdout_sha256"] = hashlib.sha256(
                b"fabricated bytes never emitted").hexdigest()
            self.assertEqual(
                report_mod._record_inconsistencies([record]), [])
            cfg_path = os.path.join(HERE, "..", "campaign.json")
            with open(cfg_path, encoding="utf-8") as handle:
                shipped = json.load(handle)
            genuine = report_mod.expected_output_from_config(shipped)
            self.assertTrue(any(
                item["field"] == "output_stdout_sha256"
                for item in report_mod._record_inconsistencies(
                    [record], genuine)))
            problems = harness_mod.check_run_package(pkg)
            self.assertTrue(any(
                "expected-output" in problem
                and "unverifiable" in problem
                for problem in problems), problems)

