    def test_malformed_argv_presents_each_shape_through_the_template(self):
        import runner as runner_mod
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            slot = plan_mod.Slot("measured", "guard", "malformed",
                                 "NO_WINDOW", 0, "nonexistent-program")
            argv = runner_mod.malformed_argv(slot, config)
            self.assertIn(runner_mod.NONEXISTENT_CHILD, argv)
            slot = plan_mod.Slot("measured", "guard", "malformed",
                                 "NO_WINDOW", 0, "malformed-timeout")
            argv = runner_mod.malformed_argv(slot, config)
            self.assertIn("not-a-timeout", argv)
            slot = plan_mod.Slot("measured", "guard", "malformed",
                                 "NO_WINDOW", 0, "out-of-range-timeout")
            argv = runner_mod.malformed_argv(slot, config)
            self.assertIn("999999999", argv)
            slot = plan_mod.Slot("measured", "guard", "malformed",
                                 "NO_WINDOW", 0, "empty-command")
            argv = runner_mod.malformed_argv(slot, config)
            self.assertIn("", argv[1:])
            slot = plan_mod.Slot("measured", "guard", "malformed",
                                 "NO_WINDOW", 0, "over-long-argument")
            argv = runner_mod.malformed_argv(slot, config)
            self.assertTrue(any(len(a) == 4096 for a in argv), argv)
            slot = plan_mod.Slot("measured", "guard", "malformed",
                                 "NO_WINDOW", 0, "non-unicode-argument")
            argv = runner_mod.malformed_argv(slot, config)
            self.assertTrue(any("\ud800" in a for a in argv), argv)
            # Identically for a competitor arm: its own template
            # carries the same shape.
            slot = plan_mod.Slot("measured", "sysprims", "malformed",
                                 "NO_WINDOW", 0, "malformed-timeout")
            argv = runner_mod.malformed_argv(slot, config)
            self.assertIn("not-a-timeout", argv)

    def test_runner_malformed_slot_records_the_arms_answer(self):
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            # Competitor arm (round-31 F2 premise): no expectation
            # is pinned for any competitor shape, so the slot is
            # presented, and answered with the recorded code,
            # whatever it is — "ok", as before.
            for shape in ("nonexistent-program", "malformed-timeout",
                          "empty-command", "over-long-argument"):
                slot = plan_mod.Slot("measured", "sysprims", "malformed",
                                     "NO_WINDOW", 0, shape)
                record = run_slot(slot, config)
                # Presented, and answered: the arm's exit code is
                # the recorded observation, whatever it is.
                self.assertEqual(record["outcome"], "ok", record)
                self.assertIsInstance(record["exit_code"], int)
                self.assertEqual(record["variant"], shape)
            # Designated arm, unpinned shape: the same observation
            # discipline — no expectation is pinned for the
            # over-long argument for any arm.
            slot = plan_mod.Slot("measured", "guard", "malformed",
                                 "NO_WINDOW", 0, "over-long-argument")
            record = run_slot(slot, config)
            self.assertEqual(record["outcome"], "ok", record)
            self.assertIsInstance(record["exit_code"], int)
            # Designated arm, pinned shapes (round-31 F2): the
            # stub arm is not the guard and does not give the
            # guard's documented refusal — it answers these
            # shapes with its own crash code, not 125 — so the
            # runner now classifies the designated slot
            # "exit-mismatch" against the pinned expectation,
            # where before the pin existed it classified "ok".
            # The classification change is the fix's construction,
            # disclosed in the round-31 landing record; the
            # recorded answer itself is asserted exactly as
            # before (an integer, the variant beside it).
            for shape in ("nonexistent-program", "malformed-timeout",
                          "empty-command"):
                slot = plan_mod.Slot("measured", "guard", "malformed",
                                     "NO_WINDOW", 0, shape)
                record = run_slot(slot, config)
                self.assertEqual(record["outcome"], "exit-mismatch",
                                 record)
                self.assertIsInstance(record["exit_code"], int)
                self.assertNotEqual(record["exit_code"], 125)
                self.assertEqual(record["variant"], shape)

