    # ------------------------------------------- collected states
    def test_collected_dimensions_render_from_the_runs_records(self):
        decisions = self.shipped_decisions()
        states = {e["dimension"]: e["state"] for e in
                  report_mod.profile_dimension_states(
                      complete_records(), decisions)}
        for dimension in COLLECTED_RECORD_DIMENSIONS:
            self.assertEqual(states[dimension], "PASS", dimension)
        # Round-27 F2: (8)'s state is computed from its artifact,
        # and the shipped artifact records every outcome
        # "not-run" — the dimension renders UNEVALUATED here, and
        # COLLECTED only once the artifact records an exercised
        # prompt class with an observed outcome (the flip is
        # pinned in Round27LandingTests).
        self.assertEqual(states[COLLECTED_MANUAL_DIMENSION],
                         "UNEVALUATED")
        ledger = {e["dimension"]: e["state"] for e in
                  report_mod.claim_ledger(complete_records(), decisions)}
        for dimension in COLLECTED_RECORD_DIMENSIONS:
            self.assertEqual(ledger[dimension], "observed-passing",
                             dimension)
        self.assertEqual(ledger[COLLECTED_MANUAL_DIMENSION],
                         "UNEVALUATED")
        with collected_usability_artifact():
            states = {e["dimension"]: e["state"] for e in
                      report_mod.profile_dimension_states(
                          complete_records(), decisions)}
            self.assertEqual(states[COLLECTED_MANUAL_DIMENSION],
                             "COLLECTED")
            ledger = {e["dimension"]: e["state"] for e in
                      report_mod.claim_ledger(
                          complete_records(), decisions)}
            self.assertEqual(ledger[COLLECTED_MANUAL_DIMENSION],
                             "collected")

    def test_collected_dimensions_without_records_are_unevaluated(self):
        # The COLLECTED entry names the instrument; it does not
        # mint evidence. A run whose records carry none of the
        # collection renders (3), (4) and (6) UNEVALUATED, with
        # their profile losses standing — the pre-fix middle
        # state (applicable, presentable, uncollected, decided
        # away) cannot re-form under the new name.
        decisions = self.shipped_decisions()
        recs = [r for r in complete_records()
                if r["path"] in ("fast", "kill")]
        states = {e["dimension"]: e["state"] for e in
                  report_mod.profile_dimension_states(recs, decisions)}
        # (4) and (6) have no records at all in this set: both
        # UNEVALUATED. ASSERTION CHANGE (round-37 F1,
        # mandated): the pre-round-37 form held (3) apart —
        # its instrument rides on every record, so it PASSed
        # here on the fast/kill cells alone. Round-37 F1
        # anchors the (3) census in build_plan()'s planned
        # populations: the malformed and scale cells are
        # planned (3) units whose records this set does not
        # carry, so they render unpaired and (3) is
        # UNEVALUATED over them, exactly as a deleted cell
        # renders in the Round37LandingTests regressions.
        for dimension in COLLECTED_RECORD_DIMENSIONS:
            self.assertEqual(states[dimension], "UNEVALUATED",
                             dimension)
        losses = report_mod.profile_dimension_losses(recs, decisions)
        # Round-27 F2: dimension (8) stands UNEVALUATED beside
        # (4) and (6) — its shipped artifact records no exercised
        # prompt class, so its loss stands too; round-37 F1
        # adds (3) beside them (four, not three).
        self.assertEqual(len(losses), 4, losses)

    def test_resource_dimension_needs_fields_or_reasons_on_records(self):
        decisions = self.shipped_decisions()
        recs = complete_records()
        for record in recs:
            record["cpu_ms"] = None
            record["peak_working_set_bytes"] = None
            record["resource_note"] = None
        states = {e["dimension"]: e["state"] for e in
                  report_mod.profile_dimension_states(recs, decisions)}
        self.assertEqual(
            states["CPU, memory, storage, network, energy, and "
                   "monetary cost"], "UNEVALUATED")
        # Absent-with-reason is collected, honestly tiered: the
        # same records with the reason named render PASS only
        # when at least one record carries a real measurement —
        # notes alone collect nothing, so they stay UNEVALUATED.
        for record in recs:
            record["resource_note"] = "GetProcessTimes failed on this arm"
        states = {e["dimension"]: e["state"] for e in
                  report_mod.profile_dimension_states(recs, decisions)}
        self.assertEqual(
            states["CPU, memory, storage, network, energy, and "
                   "monetary cost"], "UNEVALUATED")

    def test_scale_child_killed_before_publication_is_infra_failure(self):
        # Closing-run finding (round-26 landing): a wide slot
        # whose child the arm killed while it was still
        # building its tree — child.pid published, no
        # descendant PID ever published — came back "ok" with
        # an empty descendant_pids: a tree that never existed,
        # recorded as torn down. The kill path's rule (no
        # recorded identity: infrastructure failure, never
        # "ok") holds on the scale path too.
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            script = os.path.join(tmp, "publish-root-only.py")
            with open(script, "w", encoding="utf-8") as handle:
                handle.write(
                    "import os, sys, time\n"
                    "with open(os.path.join(sys.argv[1], "
                    "'child.pid'), 'w') as fh:\n"
                    "    fh.write(str(os.getpid()))\n"
                    "time.sleep(30)\n")
            config["children"]["scale_wide"] = {
                "program": sys.executable, "args": [script, "{dir}"]}
            slot = next(
                s for s in plan_mod.build_plan()
                if s.path == "scale" and s.variant == "wide-8"
                and s.kind == "measured" and s.arm == "guard")
            record = run_slot(slot, config)
            self.assertEqual(record["descendant_pids"], [])
            self.assertIsNotNone(record["child_pid"])
            self.assertEqual(record["outcome"], "infra-failure")
            self.assertIn("not presented in full",
                          record["detail"])
            self.assertEqual(
                report_mod._record_inconsistencies([record]), [])

    # --------------------------------------------------------- F2
    def test_usability_evidence_artifact_carries_the_formalized_check(self):
        path = os.path.join(HERE, "..", "usability-evidence.json")
        with open(path, encoding="utf-8") as handle:
            artifact = json.load(handle)
        self.assertIn("manual", artifact["tier"])
        classes = {r["prompt_class"] for r in artifact["records"]}
        self.assertEqual(classes, {"Windows Hello request",
                                   "credential dialog",
                                   "console password prompt"})
        # Round-28 F1: the artifact's schema states the prompt
        # classes and the outcome vocabulary, and both agree
        # with the computation's own constants and with
        # campaign.json's dimension (8) entry — code, schema
        # and note state one rule.
        self.assertEqual(set(artifact["schema"]["prompt_classes"]),
                         classes)
        self.assertEqual(set(artifact["schema"]["prompt_classes"]),
                         set(report_mod.USABILITY_PROMPT_CLASSES))
        self.assertEqual(artifact["schema"]["outcome_vocabulary"],
                         list(report_mod.USABILITY_OUTCOME_VOCABULARY))
        for record in artifact["records"]:
            # exercised is the schema's boolean (round-28): the
            # description of what the check exercises lives in
            # exercise_steps; the shipped artifact has exercised
            # nothing, so the boolean stands False.
            self.assertIs(record["exercised"], False,
                          record["prompt_class"])
            self.assertTrue(record["exercise_steps"].strip(),
                            record["prompt_class"])
            self.assertIn("observed", record)
            self.assertIn("outcome", record)
            self.assertIn(record["outcome"],
                          report_mod.USABILITY_OUTCOME_VOCABULARY)
            # Honest tier: not yet run on any Windows desktop, so
            # no outcome may claim a pass this artifact has not
            # earned.
            self.assertEqual(record["outcome"], "not-run",
                             record["prompt_class"])
            self.assertIsNone(record["observed"])
        instrument = report_mod._collection_entry(
            COLLECTED_MANUAL_DIMENSION, self.shipped_decisions())
        self.assertIn("usability-evidence.json", instrument)

