    def test_glossary_definitions_land_in_the_readme_and_are_held(self):
        with open(os.path.join(HERE, "..", "README.md"),
                  encoding="utf-8") as handle:
            readme = handle.read()
        self.assertIn(
            "a check that names a violation instead of passing "
            "it silently", readme)
        self.assertIn(
            "to create a competitor loss (or a refusal) from a "
            "record", readme)
        self.assertIn(
            "the field, label, container, element, or artifact "
            "adjacent to one already held", readme)
        # Round-31 F4: the vocabulary census's six terms land
        # beside the round-26 definitions, at the operational
        # meanings recovered from the code docstrings, the
        # FAILURE-TREE cells and the tests, and are held here
        # by their exact definitional strings. Round-32 F4:
        # STAMP and PERFECT FIXTURE are restated to their
        # computations' real breadth — STAMP to the full field
        # set pricing_stamp_defects cross-checks, PERFECT
        # FIXTURE naming BOTH fabricated complete-campaign
        # record sets — and the held strings below are the
        # restated ones.
        self.assertIn(
            "one of the values the pricing construction stamps "
            "on every pricing record, in the breadth "
            "`pricing_stamp_defects` actually cross-checks",
            readme)
        self.assertIn(
            "the owner pair's contexts — NO_WINDOW for baseline "
            "and loaded alike", readme)
        self.assertIn(
            "the item stamp (the item a record carries is the "
            "item its probe prices)", readme)
        self.assertIn(
            "the guard fingerprint's companion values "
            "guard_fingerprint.path and guard_fingerprint.size",
            readme)
        self.assertIn(
            "the exact constructed field set itself", readme)
        self.assertIn(
            "cross-checks exactly those stamps — no other record "
            "field is a stamp", readme)
        self.assertIn(
            "the recorded reference a verification is checked "
            "against instead of the package's own claim", readme)
        self.assertIn(
            "every verification the absent anchor degrades is "
            "named unverifiable", readme)
        self.assertIn(
            "one of the suite's two fabricated complete-campaign "
            "record sets", readme)
        self.assertIn(
            "`complete_fixture()` in "
            "`tests/test_output_observation.py`", readme)
        # Round-32 F4: the glossary census states and holds
        # its own term count — recomputed from the README's
        # glossary section (bullets are its '- **' lines; a
        # bullet's terms are its headwords split on ' / ', so
        # ANCHOR / ANCHORED counts two) and held against the
        # count the glossary itself states.
        import re as _re
        glossary = readme.split("## Glossary", 1)[1].split(
            "\n## ", 1)[0]
        heads = _re.findall(r"^- \*\*(.+?)\*\*", glossary,
                            _re.M)
        # Round-53 F5 AMENDMENT (open, in the same motion as
        # the definitions landing): the census lock moves
        # from 9 bullets / 10 terms to 19 bullets / 20 terms
        # — the ten materialization terms (MATERIALIZATION,
        # PROVEN, STATED, CANDIDATE, SETTLEMENT, STORING,
        # MINTING, DEFERRED, CAPTURE, TRAVERSAL) land as
        # their own bullets beside the original ten terms.
        self.assertEqual(len(heads), 19, heads)
        self.assertEqual(
            sum(len(head.split(" / ")) for head in heads), 20,
            heads)
        self.assertIn("19 bullets / 20 terms", readme)
        self.assertIn(
            "the holds and recomputation consumers never raise "
            "on the values they judge", readme)
        self.assertIn(
            "a document copy of a held quantity one ring further "
            "out than the set previously held", readme)
        self.assertIn(
            "the recomputation discipline that holds this "
            "package's documents and evidence to their sources",
            readme)
        # Round-53 F5: the materialization vocabulary's
        # definitions land in the same glossary, held here by
        # their definitional strings. Round-54 F1-F4
        # AMENDMENT (open, in the same motion as the
        # restatement landing): six definitions are restated
        # at the breadth the mechanism's executed cases
        # prove — MATERIALIZATION by provability, not actual
        # re-readability; CANDIDATE, SETTLEMENT and DEFERRED
        # with BOTH settlement paths named (the general
        # capture path and the empty candidate's captureless
        # persistence path); STORING with the fresh-wrapper
        # carrier in its enumeration; MINTING by production
        # on access, the memoizing factory included — and
        # the pinned strings below are the restated ones,
        # updated in this same motion, never slipped.
        # Round-55 F1/F2 AMENDMENT (open, in the same motion
        # as this landing): CANDIDATE is restated with a
        # pending candidate's THREE fates (settlement on
        # either path; retirement unsettled by a following
        # storing-face capture; no expiry of its own), and
        # its captureless sentence carries the round-50
        # qualification in its own text (over the marked
        # candidacy an empty candidate's object returns are
        # neutral); SETTLEMENT's binding sentence names the
        # pending candidate's retirement; DEFERRED's and
        # STORING's captureless references are scoped to
        # SETTLEMENT's stated breadth — and the pinned
        # strings below gain the new needles in this same
        # motion, never slipped.
        # Round-56 F4 AMENDMENT (open, in the same motion
        # as this landing): CANDIDATE's third fate gains
        # the fourth neutral evidence — a following read
        # that returns the entry's very object, served by
        # identity with no capture taken and no verdict
        # rendered — and the pinned strings below gain its
        # needle in this same motion, never slipped.
        # Round-57 F6 AMENDMENT (open, in the same motion
        # as this landing): the fourth member is QUALIFIED
        # in CANDIDATE's own text — the identity serve
        # holds only where the entry's object is not
        # provably re-iterable; a provably re-iterable
        # entry's object return takes the capture path
        # and settles the candidate MINTING (executed
        # under an unmarked candidacy and a marked one
        # alike) — and the third fate gains the FIFTH
        # neutral evidence, a following read whose stated
        # value is absent (the mechanism's _MISSING
        # return, before any candidate handling); the
        # pinned strings below are updated to the
        # qualified member and gain the fifth member's
        # needle in this same motion, never slipped.
        # Round-58 F5/F6 AMENDMENT (open, in the same
        # motion as this landing): the qualified member
        # gains its SECOND qualification — the MINTING
        # settlement with the entry standing holds only
        # where the capture the provably re-iterable
        # return takes states the entry's own tokens;
        # a capture stating different tokens (the
        # returned object no longer equalling the entry
        # as it stood) is judged on its face, a
        # storing-face capture standing as the entry and
        # retiring the candidate unsettled — and the
        # third fate gains the SIXTH neutral evidence,
        # an empty candidate's first object return over
        # an unmarked candidacy, the persistence-arming
        # return; the pinned strings below are updated
        # to the doubly qualified member and gain the
        # sixth member's needles in this same motion,
        # never slipped.
        # E12 AMENDMENT (open, in the same motion as the
        # landing it belongs to): the suite README is
        # restated in PTG-STE-1 standard form (Phase 5
        # design section 6.5 names the manual gating);
        # four pinned strings below change only in
        # punctuation — a comma or a colon becomes a
        # full stop, and the next word's case follows —
        # because the restated definitions carry no
        # sentence over the standard's 20 words. Every
        # word of the four strings is unchanged, and no
        # other pinned string in this test moves.
        for needle in (
                "the one read that turns a stated value into "
                "the concrete list of tokens it yields",
                "only when its re-readability is PROVEN",
                "establishes it by construction, not by the "
                "absence of a counterexample",
                "the value a mapping presents at the access a "
                "read makes",
                "a capture held pending beside a slot's "
                "retained entry",
                "an EMPTY candidate is settled STORING by its "
                "very object's persistence",
                "an empty candidate's object returns are "
                "NEUTRAL and settle nothing",
                "stands as the entry at once and retires the "
                "pending candidate unsettled",
                "a candidate has no expiry of its own",
                "a following read that returns the entry's "
                "very object, where that object is not "
                "provably re-iterable — served by identity. "
                "Taking no capture and rendering no verdict",
                "a provably re-iterable entry's very object "
                "is not so served: its return takes the "
                "capture path",
                "where the capture the return takes states "
                "the entry's own tokens, settling MINTING "
                "with the entry standing. As executed under "
                "an unmarked candidacy and a marked one alike",
                "where the capture the return takes states "
                "different tokens — the returned object no "
                "longer equalling the entry as it stood",
                "a storing-face capture there stands as the "
                "entry and retires the candidate unsettled, "
                "the entry not standing",
                "an empty candidate's first object return "
                "over an unmarked candidacy — the return "
                "that arms the persistence evidence. It "
                "decides neither side and leaves the "
                "candidate pending",
                "a following read whose stated value is "
                "absent",
                "the read returns the mechanism's missing "
                "sentinel before any candidate handling",
                "the decision that a pending candidate is "
                "storing",
                "only over an entry no minting settlement "
                "stands on",
                "a candidacy that displaced a standing minting "
                "settlement finding its empty candidate's "
                "object returns neutral",
                "its accesses return the stored object itself",
                "a fresh instance, on each access, of a "
                "wrapper type that reads the stored value",
                "each access PRODUCES the value it returns "
                "over one shared source",
                "the memoizing factory — which produces its "
                "mint once and returns that same memo object",
                "the verdict waits for a following read",
                "the single traversal a read performs over a "
                "value. Together with the tokens it yields",
                "one passage over a value by an iterator"):
            self.assertIn(needle, readme, needle)

    # --------------------------------------------------------- F5
    def module_test_counts(self):
        import ast
        counts = {}
        for name in sorted(os.listdir(HERE)):
            if name.startswith("test_") and name.endswith(".py"):
                with open(os.path.join(HERE, name),
                          encoding="utf-8") as handle:
                    module = ast.parse(handle.read())
                counts[name] = sum(
                    1 for node in ast.walk(module)
                    if isinstance(node, ast.FunctionDef)
                    and node.name.startswith("test_"))
        return counts

