class Round28LandingTests(unittest.TestCase):
    """Round-28 landing (F1-F4): the usability computation
    implements its stated rule exactly (declared prompt class,
    boolean exercised, recorded observed outcome, declared
    outcome vocabulary); the scale count hold binds DISTINCT
    descendant PIDs with the tree's roots excluded; a peak
    working set of 0 is no measurement; and the resource
    presence hold binds every record kind."""

    def shipped_decisions(self):
        cfg_path = os.path.join(HERE, "..", "campaign.json")
        with open(cfg_path, encoding="utf-8") as handle:
            config = json.load(handle)
        return report_mod.decisions_from_config(config)

    @contextlib.contextmanager
    def usability_artifact_with(self, records):
        artifact = {"instrument": "fixture manual usability check",
                    "tier": "manual/Windows-theory",
                    "records": records}
        with tempfile.NamedTemporaryFile(
                "w", suffix=".json", delete=False,
                encoding="utf-8") as handle:
            json.dump(artifact, handle)
            path = handle.name
        try:
            with mock.patch.object(
                    report_mod, "USABILITY_ARTIFACT", path):
                yield path
        finally:
            os.unlink(path)

    def honest_entry(self, **overrides):
        entry = {"prompt_class": "Windows Hello request",
                 "exercised": True,
                 "observed": "fixture: prompt shown, answered "
                             "correctly, run proceeded",
                 "outcome": "pass"}
        entry.update(overrides)
        return entry

    # ---------------------------------------------------------- F1
    def test_usability_collected_requires_the_boolean_exercised_and_a_declared_class(self):
        # The reviewer's executed mutations, as regressions:
        # each of these minted COLLECTED before the fix.
        with self.usability_artifact_with([self.honest_entry()]):
            self.assertTrue(report_mod._usability_collected())
        missing = self.honest_entry()
        del missing["exercised"]
        no_class = self.honest_entry()
        del no_class["prompt_class"]
        for entry in (
                missing,
                self.honest_entry(
                    exercised="operator showed and answered the "
                              "prompt"),
                self.honest_entry(exercised=False),
                self.honest_entry(
                    prompt_class="invented class nobody named"),
                self.honest_entry(prompt_class=""),
                no_class):
            with self.usability_artifact_with([entry]):
                self.assertFalse(report_mod._usability_collected(),
                                 entry)

    def test_usability_collected_requires_a_vocabulary_outcome_and_a_recorded_observation(self):
        # Unknown strings — including the protest's "failed"
        # with an observed lockout, "blocked" and "banana" —
        # and case/padding variants of a vocabulary word mint
        # nothing; the vocabulary's own outcomes (pass, fail)
        # with a recorded observation do; "not-run" never does.
        for outcome in ("failed", "blocked", "banana", "Pass",
                        " pass ", "not-run"):
            entry = self.honest_entry(
                outcome=outcome,
                observed="prompt unreadable; operator locked out"
                if outcome == "failed" else "something was seen")
            with self.usability_artifact_with([entry]):
                self.assertFalse(report_mod._usability_collected(),
                                 outcome)
        for outcome in ("pass", "fail"):
            with self.usability_artifact_with(
                    [self.honest_entry(outcome=outcome)]):
                self.assertTrue(report_mod._usability_collected(),
                                outcome)
        for observed in ("", None, {"seen": True}):
            with self.usability_artifact_with(
                    [self.honest_entry(observed=observed)]):
                self.assertFalse(report_mod._usability_collected(),
                                 observed)

    def test_usability_schema_code_and_campaign_note_agree(self):
        # The vocabulary and classes are stated in the evidence
        # schema and in campaign.json, and both statements
        # agree with the computation's constants; the shipped
        # all-"not-run" artifact still renders UNEVALUATED.
        # Round-29 F5: the breadth is now what the round-28
        # record claimed — the collected_rule itself is
        # compared STRUCTURALLY (parsed) across code, schema
        # and campaign.json, and the campaign entry's operative
        # clause is held to the canonical rule sentence, not
        # two substrings.
        path = os.path.join(HERE, "..", "usability-evidence.json")
        with open(path, encoding="utf-8") as handle:
            artifact = json.load(handle)
        self.assertEqual(artifact["schema"]["prompt_classes"],
                         list(report_mod.USABILITY_PROMPT_CLASSES))
        self.assertEqual(artifact["schema"]["outcome_vocabulary"],
                         list(report_mod.USABILITY_OUTCOME_VOCABULARY))
        self.assertEqual(artifact["schema"]["collected_rule"],
                         report_mod.USABILITY_COLLECTED_RULE)
        cfg_path = os.path.join(HERE, "..", "campaign.json")
        with open(cfg_path, encoding="utf-8") as handle:
            config = json.load(handle)
        self.assertEqual(config["usability_collected_rule"],
                         report_mod.USABILITY_COLLECTED_RULE)
        decisions = self.shipped_decisions()
        entry = decisions[COLLECTED_MANUAL_DIMENSION]
        self.assertIn("pass, fail, not-run", entry)
        self.assertIn("boolean true", entry)
        self.assertIn(report_mod.USABILITY_COLLECTED_RULE_TEXT,
                      entry)
        self.assertFalse(report_mod._usability_collected())
        states = {e["dimension"]: e["state"] for e in
                  report_mod.profile_dimension_states(
                      complete_records(), decisions)}
        self.assertEqual(states[COLLECTED_MANUAL_DIMENSION],
                         "UNEVALUATED")

    # ---------------------------------------------------------- F2
    def test_scale_count_hold_binds_distinct_pids_at_wide72(self):
        # The reviewer's construction: one PID repeated 72
        # times at the exact variant length passed every layer
        # before the fix. Now it is named, and the dimension
        # is not evaluated by it; the exact distinct fixture
        # is clean and over-publication still fails.
        recs = complete_records()
        victim = next(r for r in recs if r["path"] == "scale"
                      and r["kind"] == "measured"
                      and r["variant"] == "wide-72")
        victim["descendant_pids"] = [victim["descendant_pids"][0]] * 72
        items = [item for item in
                 report_mod._record_inconsistencies(recs)
                 if item["record"] is victim]
        self.assertTrue(any(item["field"] == "descendant_pids"
                            for item in items), items)
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_SCALING, recs), "UNEVALUATED")
        self.assertEqual(
            report_mod.record_consistency_losses(complete_records()),
            [])
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_SCALING, complete_records()), "PASS")
        recs = complete_records()
        victim = next(r for r in recs if r["path"] == "scale"
                      and r["kind"] == "measured"
                      and r["variant"] == "wide-72")
        victim["descendant_pids"] = \
            victim["descendant_pids"] + [999999]
        items = [item for item in
                 report_mod._record_inconsistencies(recs)
                 if item["record"] is victim]
        self.assertTrue(any(item["field"] == "descendant_pids"
                            for item in items), items)

    def test_scale_count_hold_rejects_root_substitutions(self):
        # The reviewer's second construction — the record's own
        # arm_pid repeated 8 times as a wide-8 tree — and the
        # tree-root substitution at wide-72: the roots the
        # runner/checker define (arm_pid, and child_pid, the
        # scale tree's root recorded separately) are excluded
        # from the distinct count, so neither publishes a tree.
        for variant, root_field, times in (
                ("wide-8", "arm_pid", 8),
                ("wide-72", "child_pid", 72),
                ("wide-72", "arm_pid", 72)):
            recs = complete_records()
            victim = next(r for r in recs if r["path"] == "scale"
                          and r["kind"] == "measured"
                          and r["variant"] == variant)
            victim["descendant_pids"] = [victim[root_field]] * times
            items = [item for item in
                     report_mod._record_inconsistencies(recs)
                     if item["record"] is victim]
            self.assertTrue(
                any(item["field"] == "descendant_pids"
                    for item in items), (variant, root_field, items))
            self.assertEqual(
                report_mod._collected_record_state(
                    report_mod.DIM_SCALING, recs), "UNEVALUATED")

    def test_runner_scale_classification_counts_distinct_pids_excluding_the_root(self):
        # Live construction at wide-8: the child publishes its
        # own PID (the tree root the runner records as
        # child_pid) in its ids file alongside only 7 true
        # descendants — 8 published entries, 7 distinct
        # descendants. Before the fix: "ok" at the exact list
        # length. Now the named tree was not presented in full.
        with tempfile.TemporaryDirectory() as tmp:
            config = stub_config(tmp)
            script = os.path.join(tmp, "root-wide.py")
            with open(script, "w", encoding="utf-8") as handle:
                handle.write(
                    "import os, subprocess, sys, time\n"
                    "d = sys.argv[1]\n"
                    "kids = [subprocess.Popen([sys.executable, '-S', '-c',"
                    " 'import time; time.sleep(30)'],"
                    " creationflags=getattr(subprocess, 'CREATE_NO_WINDOW', 0))"
                    " for _ in range(7)]\n"
                    "open(os.path.join(d, 'child.pid'), 'w')"
                    ".write(str(os.getpid()))\n"
                    "open(os.path.join(d, 'ids'), 'w')"
                    ".write(''.join(str(k) + chr(10) for k in"
                    " [os.getpid()] + [k.pid for k in kids]))\n"
                    "time.sleep(30)\n")
            config["children"]["scale_wide"] = {
                "program": sys.executable, "args": [script, "{dir}"]}
            slot = plan_mod.Slot("measured", "guard", "scale",
                                 "NO_WINDOW", 0, "wide-8")
            record = run_slot(slot, config)
            self.assertEqual(len(record["descendant_pids"]), 8)
            self.assertEqual(record["outcome"], "infra-failure",
                             record)
            self.assertIn("not presented in full",
                          record["detail"])
            self.assertEqual(
                report_mod._record_inconsistencies([record]), [])

    # ---------------------------------------------------------- F3
    def test_zero_peak_is_an_inconsistency_and_counts_as_no_measurement(self):
        # The reviewer's construction: every guard measured
        # record at cpu_ms 0.0 / peak 0 PASSed dimension (3)
        # on peaks no platform produces. The standing rule for
        # impossible values (round-27) is an inconsistency, and
        # that is the rule a 0 peak renders under. cpu_ms == 0
        # was NOT protested and stays admissible.
        recs = complete_records()
        for record in recs:
            if record["arm"] == "guard" \
                    and record["kind"] == "measured":
                record["cpu_ms"] = 0.0
                record["peak_working_set_bytes"] = 0
        items = report_mod._record_inconsistencies(recs)
        self.assertTrue(any(
            item["field"] == "peak_working_set_bytes"
            for item in items), items[:3])
        self.assertFalse(any(
            item["field"] == "cpu_ms" for item in items), items[:3])
        coverage = report_mod._resource_coverage(recs)
        total, cpu, peak = coverage["guard"]
        self.assertEqual((cpu, peak), (total, 0))
        self.assertNotEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "PASS")
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "UNEVALUATED")

    # ---------------------------------------------------------- F4
    def test_resource_presence_hold_names_keys_deleted_records_of_every_kind(self):
        # The reviewer's constructions: a record with all three
        # resource keys deleted was named by nothing — the
        # warmup and control kinds by nothing anywhere. Now
        # each kind is named at the per-record hold in its own
        # right, and the honest full fixture is untouched.
        self.assertEqual(
            report_mod._record_inconsistencies(complete_records()),
            [])
        for kind in ("measured", "warmup", "control"):
            recs = complete_records()
            victim = next(r for r in recs if r["kind"] == kind)
            for field in ("cpu_ms", "peak_working_set_bytes",
                          "resource_note"):
                victim.pop(field, None)
            items = [item for item in
                     report_mod._record_inconsistencies(recs)
                     if item["record"] is victim]
            self.assertTrue(
                any(item["field"] in (
                    "cpu_ms", "peak_working_set_bytes")
                    for item in items), (kind, items))


