    def test_usability_fail_only_renders_fail_with_a_standing_loss(self):
        # The reviewer's executed construction (round-29 P1):
        # the fail-only artifact ("prompt unreadable; operator
        # locked out") over the perfect fixture. Before the
        # fix: COLLECTED, ledger collected, campaign complete
        # with 0 standing losses. Now the dimension is
        # collected AND fails: profile FAIL, ledger
        # observed-failing, the usability loss standing, and
        # the campaign INCOMPLETE on exactly that loss.
        import harness as harness_mod
        fail = self.honest_entry(
            outcome="fail",
            observed="prompt unreadable; operator locked out")
        with self.usability_artifact_with([fail]):
            self.assertTrue(report_mod._usability_collected())
            self.assertEqual(report_mod._usability_state(), "FAIL")
