    def test_fractional_peak_is_named_and_counts_toward_no_coverage(self):
        # The reviewer's constructions (round-29 P2): peaks of
        # 0.5, 4096.5 and the subnormal 5e-324 drew no
        # inconsistency and an all-guard 0.5 fixture PASSed
        # dimension (3). Both runner sources produce an
        # integer, so a fractional peak is now named and
        # counts toward no coverage; integer and
        # integer-valued peaks remain measurements.
        for value in (0.5, 4096.5, 5e-324):
            self.assertFalse(report_mod._is_plausible_peak(value),
                             value)
        for value in (4096, 4096.0):
            self.assertTrue(report_mod._is_plausible_peak(value),
                            value)
        recs = complete_records()
        for record in recs:
            if record["arm"] == "guard" \
                    and record["kind"] == "measured":
                record["peak_working_set_bytes"] = 0.5
        items = report_mod._record_inconsistencies(recs)
        self.assertTrue(any(
            item["field"] == "peak_working_set_bytes"
            for item in items), items[:3])
        total, cpu, peak = report_mod._resource_coverage(
            recs)["guard"]
        self.assertEqual((cpu, peak), (total, 0))
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "UNEVALUATED")

    # ---------------------------------------------------------- F3
    def test_resource_presence_hold_partial_deletion_matrix(self):
        # The runner's note semantics, from its code: every
        # record is CONSTRUCTED with both resource keys, and
        # a note names a collection failure — in the infra
        # states (not spawned / never spawned / not reaped)
        # and in the by-note platform counter failures on a
        # completed slot (a Windows call failing for one
        # field only, the other numeric beside the note; or a
        # platform with no per-child accounting). The runner
        # never deletes a key. The matrix, pinned per cell:
        def named(mutate, kind="measured"):
            recs = complete_records()
            victim = next(r for r in recs if r["kind"] == kind)
            mutate(victim)
            return [item["field"] for item in
                    self.resource_items(recs, victim)]

        both = ["cpu_ms", "peak_working_set_bytes"]
        # Keys deleted, note retained, completed measurement:
        # named for both fields (round-29 P3's construction).
        self.assertEqual(named(lambda v: (
            v.pop("cpu_ms"), v.pop("peak_working_set_bytes"),
            v.update(resource_note="GetProcessTimes failed on this arm"))), both)
        # Keys deleted, note retained, infra record: named
        # too — the runner's infra records carry their keys
        # (null values, note present); it deletes none.
        self.assertEqual(named(lambda v: (
            v.pop("cpu_ms"), v.pop("peak_working_set_bytes"),
            v.update(resource_note="arm never spawned; no process to account",
                     outcome="infra-failure"))), both)
        # One key deleted, the other numeric, note retained:
        # the deleted field alone is named.
        self.assertEqual(named(lambda v: (
            v.pop("cpu_ms"),
            v.update(resource_note="GetProcessTimes failed on this arm"))),
            ["cpu_ms"])
        # Null values with a note, completed measurement: NOT
        # named — the by-note collection-failure shape (the
        # Windows counter failure / no-accounting platform).
        self.assertEqual(named(lambda v: v.update(
            cpu_ms=None, peak_working_set_bytes=None,
            resource_note="GetProcessTimes failed on this arm")), [])
        # Null values with a note, infra record: NOT named —
        # the infra collection-failure shape.
        self.assertEqual(named(lambda v: v.update(
            cpu_ms=None, peak_working_set_bytes=None,
            resource_note="arm never spawned; no process to "
                          "account", outcome="infra-failure")), [])
        # The honest partial shape: cpu numeric beside the
        # note, peak null with its reason: NOT named.
        self.assertEqual(named(lambda v: v.update(
            peak_working_set_bytes=None,
            resource_note="GetProcessMemoryInfo failed on "
                          "this arm")), [])
        # Values present with a note also present: the fields
        # are plausible counters; nothing is named for them.
        self.assertEqual(named(lambda v: v.update(
            resource_note="GetProcessTimes failed on this arm")), [])
        # Values absent and note absent (all three keys
        # deleted): named for both fields.
        self.assertEqual(named(lambda v: (
            v.pop("cpu_ms"), v.pop("peak_working_set_bytes"),
            v.pop("resource_note"))), both)
        # Null values, note key deleted: named for both.
        self.assertEqual(named(lambda v: (
            v.update(cpu_ms=None, peak_working_set_bytes=None),
            v.pop("resource_note"))), both)
        # The dimension state agrees: a measured record whose
        # keys are deleted with a note retained is not
        # accounted, so the collection is incomplete.
        recs = complete_records()
        victim = next(r for r in recs if r["kind"] == "measured")
        victim.pop("cpu_ms")
        victim.pop("peak_working_set_bytes")
        victim["resource_note"] = "GetProcessTimes failed on this arm"
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "UNEVALUATED")

