class Round40LandingTests(unittest.TestCase):
    """Round-40 landing (F1-F4): the (3) gate keys by the
    slot-derived variant on every path and binds its plan-0
    rule per (cell, arm); unplanned records are excluded
    from every evidence consumer (resource coverage,
    decompose/pricing populations, kill state and
    competitor-loss evidence); and the fast-argv derivation
    mirrors the construction's tokenization for every config
    shape the construction accepts."""

    def shipped_config(self):
        return shipped_config()

    # ---------------------------------------------------------- F1
    def test_gate_keys_by_the_slot_derived_variant_on_every_path(self):
        # The round-40 reviewer's P1 constructions, verbatim:
        # a malformed case-relabel (Empty-Command), the
        # identical scale relabel (Wide-8), and a fast
        # carried string (fast-999). Before the fix the
        # malformed relabel minted 6 UNPLANNED units and 6
        # planned-shortfall units for one keying defect and
        # the fast string manufactured an UNPLANNED cell,
        # while the scale relabel compared in its planned
        # cell. Now every path keys by the slot: no
        # UNPLANNED cell and no planned-shortfall pair is
        # minted from a label, each construction renders as
        # its planned cell's records, (3) PASSes over each,
        # the honest fixture holds 144 compared, and the
        # mislabels are named once, in the variant channel.
        recs = complete_records()
        for record in recs:
            if record["path"] == "malformed" \
                    and record["context"] == "NO_WINDOW" \
                    and record.get("variant") == "empty-command":
                record["variant"] = "Empty-Command"
        losses, unpaired, compared, _f = \
            report_mod._paired_cost_comparison_detail(recs)
        self.assertEqual(
            [e for e in unpaired if "Empty-Command" in e], [])
        self.assertEqual(
            [e for e in unpaired if "'empty-command'" in e
             and "NO_WINDOW" in e], [])
        self.assertEqual(len(compared), 144, compared[:2])
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "PASS")
        variant_items = [item for item in
                         report_mod._record_inconsistencies(recs)
                         if item["field"] == "variant"]
        self.assertTrue(variant_items)
        self.assertTrue(all(
            "Empty-Command" in item["detail"]
            for item in variant_items), variant_items[:2])

        recs = complete_records()
        for record in recs:
            if record["path"] == "scale" \
                    and record["context"] == "NO_WINDOW" \
                    and record.get("variant") == "wide-8":
                record["variant"] = "Wide-8"
        losses, unpaired, compared, _f = \
            report_mod._paired_cost_comparison_detail(recs)
        self.assertEqual(
            [e for e in unpaired if "ide-8" in e], [])
        self.assertEqual(len(compared), 144, compared[:2])
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "PASS")

        recs = complete_records()
        for record in recs:
            if record["path"] == "fast" \
                    and record["context"] == "NO_WINDOW" \
                    and record["kind"] == "measured" \
                    and record["rep"] < 3:
                record["variant"] = "fast-999"
        losses, unpaired, compared, _f = \
            report_mod._paired_cost_comparison_detail(recs)
        self.assertEqual(
            [e for e in unpaired + compared
             if "fast-999" in e], [])
        self.assertEqual(len(compared), 144, compared[:2])
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "PASS")

        losses, unpaired, compared, _f = \
            report_mod._paired_cost_comparison_detail(
                complete_records())
        self.assertEqual((len(losses), len(unpaired),
                          len(compared)), (0, 0, 144))

    # ---------------------------------------------------------- F2
    def test_plan_zero_rule_binds_per_cell_arm(self):
        # The round-40 reviewer's P2 construction: the plan
        # patched at the seam the gate reads, identical to
        # the shipped plan except the malformed / NO_WINDOW /
        # empty-command cell carries no guard slots. Before
        # the fix the zero-planned arm's records COMPARED,
        # rendered "(4/0)" inside a compared unit. Now the
        # unit renders UNPLANNED for that arm — the plan
        # count stated as 0 for the zero side, the other
        # side's stated as the plan's — no compared unit
        # renders a count over a zero denominator, and the
        # shipped symmetric plan compares the cell as before.
        slots = [slot for slot in plan_mod.build_plan()
                 if not (slot.kind == "measured"
                         and slot.path == "malformed"
                         and slot.context == "NO_WINDOW"
                         and slot.variant == "empty-command"
                         and slot.arm == "guard")]
        with mock.patch.object(
                report_mod, "build_plan",
                lambda seed=None: slots):
            losses, unpaired, compared, _f = \
                report_mod._paired_cost_comparison_detail(
                    complete_records())
            mine_unpaired = [e for e in unpaired
                             if "'empty-command'" in e
                             and "NO_WINDOW" in e
                             and "sysprims" in e
                             and "cpu_ms" in e]
            self.assertTrue(mine_unpaired, unpaired[:3])
            for entry in mine_unpaired:
                self.assertIn("UNPLANNED", entry)
                self.assertIn("0 planned record(s)", entry)
                self.assertIn("carries 3 of its 3", entry)
            self.assertEqual(
                [e for e in compared
                 if "'empty-command'" in e
                 and "NO_WINDOW" in e], [])
            for entry in compared:
                self.assertNotIn("/0)", entry)
            self.assertEqual(
                report_mod._collected_record_state(
                    report_mod.DIM_RESOURCE,
                    complete_records()), "UNEVALUATED")
        losses, unpaired, compared, _f = \
            report_mod._paired_cost_comparison_detail(
                complete_records())
        self.assertTrue(any(
            "'empty-command'" in e and "NO_WINDOW" in e
            for e in compared), compared[:3])

    # ---------------------------------------------------------- F3
    def test_unplanned_records_are_excluded_from_every_evidence_consumer(self):
        # The round-40 reviewer's P3 constructions, verbatim
        # in shape: one wide-999 record softening (3)'s
        # earned FAIL through _resource_coverage; ninety
        # fabricated fast-999 records moving the decompose
        # median and erasing a pricing standing loss; one
        # kill-999 record flipping a kill state and minting
        # a competitor-loss entry. Before the fix all three
        # moved their numbers. Now an unplanned record —
        # matching no plan slot under the slot-accounting
        # identity — is evidence nowhere: every population
        # below is the honest fixture's own, and the genuine
        # planned populations are unmoved everywhere.
        import copy
        # Coverage: the designated arm's planned records
        # earn FAIL (every counter an accounted null); one
        # plausible wide-999 record must not soften it.
        recs = complete_records()
        for record in recs:
            if record["kind"] == "measured" \
                    and record["arm"] == "guard":
                record["cpu_ms"] = None
                record["peak_working_set_bytes"] = None
                record["resource_note"] = (
                    "arm never spawned; no process to account")
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "FAIL")
        honest_coverage = report_mod._resource_coverage(recs)
        recs.append({
            "kind": "measured", "arm": "guard", "path": "scale",
            "context": "NO_WINDOW", "rep": 900,
            "variant": "wide-999", "cpu_ms": 10.0,
            "peak_working_set_bytes": 4096, "outcome": "ok",
            "elapsed_ms": 1.0, "descendant_pids": [1, 2, 3],
            "arm_pid": 50, "child_pid": 51})
        self.assertEqual(
            report_mod._resource_coverage(recs),
            honest_coverage)
        self.assertEqual(
            report_mod._resource_coverage(recs)["guard"],
            (420, 0, 0))
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, recs), "FAIL")
        # Pricing: ninety fabricated fast records must move
        # no median and erase no standing loss.
        pricing = {"kind": "pricing-probe-evidence",
                   "guard_fingerprint": "x",
                   "items": {"console probe + console finish":
                             {"ms": 5000.0}}}
        recs = complete_records()
        honest_decomp = report_mod.decompose(
            recs, pricing, "NO_WINDOW")
        self.assertEqual(
            honest_decomp["distance_above_floor_ms"], 10.0)
        self.assertTrue(honest_decomp["inconsistent"])
        honest_losses = report_mod.pricing_inconsistency_losses(
            recs, pricing)
        self.assertEqual(len(honest_losses), 2, honest_losses)
        source = next(
            r for r in recs if r["path"] == "fast"
            and r["arm"] == "guard"
            and r["context"] == "NO_WINDOW"
            and r["kind"] == "measured" and r["rep"] == 0)
        for rep in range(900, 990):
            fab = copy.deepcopy(source)
            fab["rep"] = rep
            fab["elapsed_ms"] = 100000.0
            fab["variant"] = "fast-999"
            recs.append(fab)
        self.assertEqual(
            report_mod._median(recs, "guard", "fast",
                               "NO_WINDOW"), 62.0)
        decomp = report_mod.decompose(recs, pricing, "NO_WINDOW")
        self.assertEqual(decomp["distance_above_floor_ms"], 10.0)
        self.assertEqual(
            report_mod.pricing_inconsistency_losses(
                recs, pricing), honest_losses)
        # Kill state: one fabricated kill-999 survival must
        # flip no state and mint no competitor-loss entry,
        # at the competitor_losses consumer or in the
        # standing-loss listing it feeds.
        recs = complete_records()
        self.assertEqual(
            report_mod._kill_state(recs, "nuewframe",
                                   "NO_WINDOW")[0], "clean")
        source = next(
            r for r in recs if r["path"] == "kill"
            and r["arm"] == "nuewframe"
            and r["context"] == "NO_WINDOW"
            and r["kind"] == "measured" and r["rep"] == 0)
        fab = copy.deepcopy(source)
        fab["rep"] = 900
        fab["variant"] = "kill-999"
        fab["outcome"] = "descendant-survived"
        fab["survivor"] = True
        recs.append(fab)
        self.assertEqual(
            report_mod._kill_state(recs, "nuewframe",
                                   "NO_WINDOW")[0], "clean")
        self.assertEqual(report_mod.competitor_losses(recs), [])
        self.assertFalse(any(
            loss.startswith(report_mod.COMPETITOR_LOSS_PREFIX)
            for loss in report_mod.standing_losses(
                recs, FULL_COUNTS)), )

    # ---------------------------------------------------------- F4
    def test_derivation_mirrors_the_constructions_tokenization(self):
        # The round-40 reviewer's P4 constructions, verbatim:
        # args stated as a string (per character) and as a
        # dict (by keys), a template stated as a string (per
        # character), and a template token stated as a list
        # or tuple (appended verbatim). Before the fix each
        # derived (None, gap) and the string/dict args forms
        # minted 192 underived items over the genuine
        # fixture, while the runner built definite vectors.
        # Now each derives the built length for every arm,
        # no underived item is minted, genuine configs
        # derive exactly as before, and a genuinely
        # unbuildable shape still names its gap.
        import copy
        base = self.shipped_config()
        arms = ("guard", "processkit", "nuewframe", "sysprims")

        def lengths(config):
            return {arm: report_mod._plan_fast_argv_length(
                arm, config) for arm in arms}

        def underived(config):
            return [item for item in
                    report_mod._record_inconsistencies(
                        complete_records(), config=config)
                    if "underived" in item["detail"]]

        config = copy.deepcopy(base)
        text_args = "relay 0"
        config["children"]["fast"]["args"] = text_args
        extra_tokens = len(text_args) - len(base["children"]["fast"]["args"])
        self.assertEqual(lengths(config), {
            arm: count + extra_tokens
            for arm, count in SHIPPED_FAST_ARGV_LENGTHS.items()})
        self.assertEqual(underived(config), [])

        config = copy.deepcopy(base)
        config["children"]["fast"]["args"] = {"relay": 0, "x": 1}
        self.assertEqual(lengths(config), SHIPPED_FAST_ARGV_LENGTHS)
        self.assertEqual(underived(config), [])

        for arm in arms:
            config = copy.deepcopy(base)
            config["arms"][arm]["templates"]["fast"] = "ab{child}"
            self.assertEqual(
                report_mod._plan_fast_argv_length(arm, config),
                10, arm)
            self.assertIsNone(
                report_mod._plan_fast_argv_budget_gap(
                    arm, config), arm)

        for token in (["x"], ("x",)):
            for arm in arms:
                config = copy.deepcopy(base)
                config["arms"][arm]["templates"]["fast"] = [
                    "{timeout_s}", token, "{child}",
                    "{child_args}"]
                self.assertEqual(
                    report_mod._plan_fast_argv_length(
                        arm, config), 6, (arm, token))
                self.assertIsNone(
                    report_mod._plan_fast_argv_budget_gap(
                        arm, config), (arm, token))

        self.assertEqual(lengths(base), SHIPPED_FAST_ARGV_LENGTHS)

        # Genuinely unbuildable shapes still name their gap:
        # a non-iterable args value (the runner's list()
        # raises there too), a non-iterable template, and an
        # integer template token (the expansion's own string
        # tests refuse it).
        config = copy.deepcopy(base)
        config["children"]["fast"]["args"] = 123
        self.assertIsNone(
            report_mod._plan_fast_argv_length("guard", config))
        self.assertIn(
            "present but unusable",
            report_mod._plan_fast_argv_budget_gap(
                "guard", config))
        config = copy.deepcopy(base)
        config["arms"]["guard"]["templates"]["fast"] = 123
        self.assertIsNone(
            report_mod._plan_fast_argv_length("guard", config))
        self.assertIn(
            "present but unusable",
            report_mod._plan_fast_argv_budget_gap(
                "guard", config))
        config = copy.deepcopy(base)
        config["arms"]["guard"]["templates"]["fast"] = [
            "{timeout_s}", 123, "{child}", "{child_args}"]
        self.assertIsNone(
            report_mod._plan_fast_argv_length("guard", config))
        gap = report_mod._plan_fast_argv_budget_gap(
            "guard", config)
        self.assertIn("present but unusable", gap)
        self.assertIn("123", gap)

    # ------------------------------------------------- documents
    def test_verification_restatements_state_the_round40_truths(self):
        # Harness by subject (documents/census, by the
        # split rule's own examples): VERIFICATION's
        # dimension-(3) statement states the round-40 gate
        # and evidence rules, and its dimension-(6)
        # statement is restated to the construction's
        # tokenization breadth — a future edit that drops
        # either restatement fails here.
        import re
        with open(os.path.join(HERE, "..", "VERIFICATION.md"),
                  encoding="utf-8") as handle:
            text = handle.read()
        section3 = text.split(
            "- **(3) CPU", 1)[1].split("- **(4) Scaling", 1)[0]
        section3 = re.sub(r"\s+", " ", section3)
        for needle in (
                "Round-40 F1",
                "slot-derived variant on every path",
                "Round-40 F2",
                "per (cell, arm)",
                "Round-40 F3",
                "not evidence"):
            self.assertIn(needle, section3, needle)
        section6 = text.split(
            "- **(6) Security boundaries", 1)[1].split(
            "- **(7) Compatibility", 1)[0]
        section6 = re.sub(r"\s+", " ", section6)
        for needle in (
                "Round-40 F4",
                "per character",
                "by its keys",
                "sequence tokens appended verbatim",
                "only shapes where the construction itself "
                "cannot build one"):
            self.assertIn(needle, section6, needle)


class Round41LandingTests(unittest.TestCase):
    """Round-41 landing (F1-F6): the planned population is
    multiplicity-exact (a Counter, slot accounting's own
    semantics) in every evidence consumer; the freeze gate's
    label and inconsistency readers judge that population;
    arm identity is held against the record's second encoding
    (its argv's executable token); the fast-argv derivation
    never consumes a one-shot iterator (materialize once at
    the shared read, written back); variant absence is
    named; and every unplanned record's evidenced fault is
    listed in its own name. Plus the adopted breadth
    correction: VERIFICATION's F4 statement is restated —
    sequence tokens derive verbatim only for
    placeholder-free sequences."""

    def shipped_config(self):
        return shipped_config()

    # ---------------------------------------------------------- F1
    def test_the_planned_population_is_multiplicity_exact(self):
        # The round-41 reviewer's P1 constructions, verbatim:
        # 100 copies of one planned guard fast slot (elapsed
        # mutated) against the median, ONE duplicate copy
        # against resource coverage, and 90 copies against
        # the pricing decomposition. Before the fix the
        # membership filter admitted every copy at full
        # multiplicity: the median moved 62.0 -> 100000.0,
        # one copy softened (3) FAIL -> UNEVALUATED, and 90
        # copies erased a pricing INCONSISTENCY (distance
        # 10.0 -> 49979.0, losses 2 -> 1). Now the population
        # is the plan's Counter: a copy beyond its slot's
        # planned count is UNPLANNED — it renders as
        # unplanned naming (slot accounting's duplicate
        # entries), never as evidence, and the honest
        # populations are unmoved.
        import copy
        recs = complete_records()
        self.assertEqual(len(report_mod._planned_records(recs)),
                         1940)
        self.assertEqual(
            report_mod._median(recs, "guard", "fast", "NO_WINDOW"),
            62.0)
        src = next(r for r in recs
                   if r["arm"] == "guard" and r["path"] == "fast"
                   and r["context"] == "NO_WINDOW"
                   and r["kind"] == "measured" and r["rep"] == 0)
        dups = []
        for _ in range(100):
            dup = copy.deepcopy(src)
            dup["elapsed_ms"] = 100000.0
            dups.append(dup)
        recs2 = recs + dups
        self.assertEqual(len(report_mod._planned_records(recs2)),
                         1940)
        self.assertEqual(
            report_mod._median(recs2, "guard", "fast", "NO_WINDOW"),
            62.0)
        self.assertTrue(any(
            "101 copies of one plan slot" in loss
            for loss in report_mod.slot_accounting_losses(recs2)))
        # Coverage: the all-null guard population FAILs (3);
        # one duplicate of a planned record softens nothing.
        nulled = complete_records()
        for record in nulled:
            if record["kind"] == "measured" \
                    and record["arm"] == "guard":
                record["cpu_ms"] = None
                record["peak_working_set_bytes"] = None
                record["resource_note"] = \
                    "arm never spawned; no process to account"
        self.assertEqual(
            report_mod._resource_coverage(nulled)["guard"],
            (420, 0, 0))
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, nulled), "FAIL")
        nulled.append(copy.deepcopy(src))
        self.assertEqual(
            report_mod._resource_coverage(nulled)["guard"],
            (420, 0, 0))
        self.assertEqual(
            report_mod._collected_record_state(
                report_mod.DIM_RESOURCE, nulled), "FAIL")
        self.assertTrue(any(
            "2 copies of one plan slot" in loss
            for loss in report_mod.slot_accounting_losses(nulled)))
        # Pricing: 90 copies erase no INCONSISTENCY.
        pricing = {"kind": "pricing-probe-evidence",
                   "guard_fingerprint": "x",
                   "items": {"console probe + console finish":
                             {"ms": 5000.0}}}
        priced = complete_records()
        self.assertEqual(
            report_mod.decompose(
                priced, pricing, "NO_WINDOW")[
                    "distance_above_floor_ms"],
            10.0)
        self.assertEqual(
            len(report_mod.pricing_inconsistency_losses(
                priced, pricing)), 2)
        srcf = next(r for r in priced
                    if r["path"] == "fast" and r["arm"] == "guard"
                    and r["context"] == "NO_WINDOW"
                    and r["kind"] == "measured" and r["rep"] == 0)
        for _ in range(90):
            fab = copy.deepcopy(srcf)
            fab["elapsed_ms"] = 100000.0
            priced.append(fab)
        decomp = report_mod.decompose(priced, pricing, "NO_WINDOW")
        self.assertEqual(decomp["distance_above_floor_ms"], 10.0)
        self.assertEqual(
            len(report_mod.pricing_inconsistency_losses(
                priced, pricing)), 2)
        self.assertEqual(
            report_mod._median(priced, "guard", "fast",
                               "NO_WINDOW"), 62.0)

    # ---------------------------------------------------------- F2
    def test_the_freeze_gates_label_readers_judge_the_planned_population(self):
        # The round-41 reviewer's P2 constructions, verbatim:
        # one fabricated guard rep-999 record per label —
        # exit-mismatch, output-mismatch, infra-failure —
        # against the freeze gate. Before the fix the gate's
        # label readers (guard_all / guard_fast) and its
        # inconsistency readers iterated every record: the
        # exit-mismatch fabrication flipped exit-code
        # correctness to FAIL and minted a freeze-gate
        # standing loss, the output-mismatch fabrication
        # flipped output correctness to FAIL, and the
        # infra-failure fabrication softened exit-code
        # correctness to UNEVALUATED. Now every reader in
        # the gate judges the planned population: the
        # fabricated records move no gate dimension and no
        # standing loss (they stand as named incompleteness
        # in the channels that name records), and the honest
        # gate is unmoved.
        import copy
        recs = complete_records()
        gate0 = {(e["dimension"], e["context"]): e["outcome"]
                 for e in report_mod.freeze_gate(recs)}
        self.assertEqual(
            gate0[("exit-code correctness", "NO_WINDOW")], "PASS")
        self.assertEqual(
            gate0[("output correctness", "NO_WINDOW")], "PASS")
        self.assertEqual(
            len(report_mod.standing_losses(recs, FULL_COUNTS)), 0)
        base = next(r for r in recs
                    if r["arm"] == "guard" and r["path"] == "fast"
                    and r["context"] == "NO_WINDOW"
                    and r["kind"] == "measured")
        fab = copy.deepcopy(base)
        fab["rep"] = 999
        fab["outcome"] = "exit-mismatch"
        fab["exit_code"] = 7
        gate1 = {(e["dimension"], e["context"]): e["outcome"]
                 for e in report_mod.freeze_gate(recs + [fab])}
        self.assertEqual(
            gate1[("exit-code correctness", "NO_WINDOW")], "PASS")
        self.assertEqual(
            [loss for loss in report_mod.standing_losses(
                recs + [fab], FULL_COUNTS)
             if "freeze gate" in loss], [])
        fab2 = copy.deepcopy(base)
        fab2["rep"] = 999
        fab2["outcome"] = "output-mismatch"
        gate2 = {(e["dimension"], e["context"]): e["outcome"]
                 for e in report_mod.freeze_gate(recs + [fab2])}
        self.assertEqual(
            gate2[("output correctness", "NO_WINDOW")], "PASS")
        fab3 = copy.deepcopy(base)
        fab3["rep"] = 999
        fab3["outcome"] = "infra-failure"
        gate3 = {(e["dimension"], e["context"]): e["outcome"]
                 for e in report_mod.freeze_gate(recs + [fab3])}
        self.assertEqual(
            gate3[("exit-code correctness", "NO_WINDOW")], "PASS")

    # ---------------------------------------------------------- F3
    def test_arm_identity_is_held_against_the_records_second_encoding(self):
        # The round-41 reviewer's P3 constructions, verbatim:
        # pairwise arm-LABEL swaps — guard<->sysprims on the
        # fast rep-0 slot, processkit<->sysprims on the
        # malformed rep-0 slot — each record keeping the
        # other arm's executed vector. Before the fix every
        # consumer read only the filed label: slot accounting
        # stayed exact, no inconsistency named either record,
        # standing losses rendered 0 and every gate dimension
        # PASSed over two wrong binaries. Now the record's
        # second encoding is held: an argv[0] that is another
        # product arm's configured executable is named in the
        # argv channel, and the swaps cannot render standing
        # losses 0. Genuine records, whose tokens agree with
        # their filed arms, are unmoved.
        recs = complete_records()
        self.assertEqual(
            [i for i in report_mod._record_inconsistencies(recs)
             if i["field"] == "argv"
             and "configured executable of arm" in i["detail"]],
            [])
        g = next(r for r in recs
                 if r["arm"] == "guard" and r["path"] == "fast"
                 and r["context"] == "NO_WINDOW"
                 and r["kind"] == "measured" and r["rep"] == 0)
        s = next(r for r in recs
                 if r["arm"] == "sysprims" and r["path"] == "fast"
                 and r["context"] == "NO_WINDOW"
                 and r["kind"] == "measured" and r["rep"] == 0)
        g["arm"], s["arm"] = "sysprims", "guard"
        self.assertEqual(report_mod.slot_accounting_losses(recs),
                         [])
        items = [i for i in report_mod._record_inconsistencies(recs)
                 if i["record"] in (g, s)
                 and i["field"] == "argv"
                 and "configured executable of arm" in i["detail"]]
        self.assertEqual(len(items), 2)
        self.assertTrue(any("sysprims" in i["detail"]
                            and "process-tree-guard" in i["detail"]
                            for i in items))
        self.assertEqual(
            len(report_mod.standing_losses(recs, FULL_COUNTS)), 2)
        recs = complete_records()
        p = next(r for r in recs
                 if r["arm"] == "processkit"
                 and r["path"] == "malformed"
                 and r["context"] == "NO_WINDOW"
                 and r["kind"] == "measured" and r["rep"] == 0)
        s2 = next(r for r in recs
                  if r["arm"] == "sysprims"
                  and r["path"] == "malformed"
                  and r["context"] == "NO_WINDOW"
                  and r["kind"] == "measured" and r["rep"] == 0)
        p["arm"], s2["arm"] = "sysprims", "processkit"
        self.assertEqual(report_mod.slot_accounting_losses(recs),
                         [])
        items = [i for i in report_mod._record_inconsistencies(recs)
                 if i["record"] in (p, s2)
                 and i["field"] == "argv"
                 and "configured executable of arm" in i["detail"]]
        self.assertEqual(len(items), 2)
        # ProcessKit's required timeout, event and input tokens also make
        # its vector too long for the slot now labeled as sysprims.
        losses = report_mod.standing_losses(recs, FULL_COUNTS)
        self.assertEqual(len(losses), 3, losses)
        self.assertTrue(any("sysprims/malformed" in loss
                            and "not the exact vector" in loss
                            for loss in losses), losses)

    # ---------------------------------------------------------- F4
    def test_the_derivation_never_consumes_a_one_shot_iterator(self):
        # The round-41 reviewer's P4 constructions, verbatim:
        # a generator as the fast child spec's args, and a
        # generator as the guard's fast template. Before the
        # fix the derivation's list() coercion and the
        # runner's reads consumed the shared iterator: the
        # same configuration object derived (7, None) then
        # (5, None), the runner's child_for after any
        # derivation saw [], and a generator template derived
        # 5 then 1. Now the value is materialized ONCE at the
        # read the derivation and the runner share and
        # written back into the configuration object, so the
        # budget is a function of the configuration: repeated
        # derivations agree in both orders, and the runner
        # sees the full vector after any derivation. The
        # adopted breadth correction stands beside it: a
        # sequence token carrying a timeout placeholder
        # raises on BOTH sides (a derivation gap at that
        # token; the construction raising in the same
        # expansion), while a placeholder-free sequence token
        # derives and builds as the one token appended.
        import copy
        base = shipped_config()
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"]["args"] = \
            (x for x in ["relay", "0"])
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        slot = plan_mod.Slot("measured", "guard", "fast",
                             "NO_WINDOW", 0)
        self.assertEqual(
            runner_mod.child_for(slot, cfg),
            ("build\\testkit.exe", ["relay", "0"]))
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"]["args"] = \
            (x for x in ["relay", "0"])
        program, child_args = runner_mod.child_for(slot, cfg)
        self.assertEqual(child_args, ["relay", "0"])
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        cfg = copy.deepcopy(base)
        cfg["arms"]["guard"]["templates"]["fast"] = (
            t for t in ["{timeout_s}", "{child}", "{child_args}"])
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        cfg = copy.deepcopy(base)
        cfg["arms"]["guard"]["templates"]["fast"] = (
            t for t in ["{timeout_s}", "{child}", "{child_args}"])
        self.assertEqual(
            arms_mod.resolve_template("guard", "fast", cfg),
            ["{timeout_s}", "{child}", "{child_args}"])
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        for token in (["{timeout_s}"], ("{timeout_ms}",)):
            cfg = copy.deepcopy(base)
            cfg["arms"]["guard"]["templates"]["fast"] = \
                [token, "{child}", "{child_args}"]
            length, gap = report_mod._plan_fast_argv_derivation(
                "guard", cfg)
            self.assertIsNone(length)
            self.assertIsNotNone(gap)
            bad_slot = plan_mod.Slot(
                "measured", "guard", "malformed", "NO_WINDOW", 0,
                "empty-command")
            with self.assertRaises(Exception):
                runner_mod.malformed_argv(bad_slot, cfg)
        cfg = copy.deepcopy(base)
        cfg["arms"]["guard"]["templates"]["fast"] = \
            [["x"], "{child}", "{child_args}"]
        length, gap = report_mod._plan_fast_argv_derivation(
            "guard", cfg)
        self.assertIsNone(gap)
        built = [arms_mod.arm_executable("guard", cfg)] \
            + arms_mod.expand_template(
                arms_mod.resolve_template("guard", "fast", cfg),
                runner_mod.FAST_TIMEOUT_S,
                *runner_mod.child_for(slot, cfg))
        self.assertEqual(length, len(built))

    # ---------------------------------------------------------- F5
    def test_variant_absence_is_named(self):
        # The round-41 reviewer's P5 construction, verbatim:
        # variant=None on every malformed record. Before the
        # fix the variant hold named only a DISAGREEING
        # label: the construction yielded 0 variant items,
        # (3) and (6) PASSed and standing losses rendered 0
        # over 192 erased labels. Now absence is named in
        # the same channel — the runner stamps the slot's
        # encoded shape on every malformed and scale record
        # it writes, so a missing, null, empty or untyped
        # label is an erased written field — and the
        # construction renders variant items and standing
        # losses, never a clean campaign. Records with
        # present labels are unmoved.
        recs = complete_records()
        for record in recs:
            if record["path"] == "malformed":
                record["variant"] = None
        items = [i for i in report_mod._record_inconsistencies(recs)
                 if i["field"] == "variant"]
        self.assertEqual(len(items), 192)
        self.assertTrue(all(
            "variant is None" in i["detail"] for i in items))
        self.assertEqual(
            len(report_mod.standing_losses(recs, FULL_COUNTS)),
            192)
        text = report_mod.render(recs, FULL_COUNTS, {"guard": {}})
        self.assertIn("STATUS: INCOMPLETE", text)
        # The other absence forms name the same absence: a
        # deleted key, an empty string, an untyped value —
        # on the scale path as on the malformed path.
        for mutate in (
                lambda r: r.pop("variant"),
                lambda r: r.update({"variant": ""}),
                lambda r: r.update({"variant": 7})):
            sample = complete_records()
            targets = [
                next(r for r in sample
                     if r["path"] == path
                     and r["kind"] == "measured"
                     and r["context"] == "NO_WINDOW")
                for path in ("malformed", "scale")]
            for record in targets:
                mutate(record)
            named = [i for i in
                     report_mod._record_inconsistencies(sample)
                     if i["field"] == "variant"
                     and i["record"] in targets]
            self.assertEqual(len(named), 2)
        honest = complete_records()
        self.assertEqual(
            [i for i in report_mod._record_inconsistencies(honest)
             if i["field"] == "variant"
             and "variant is None" in i["detail"]
             or (i["field"] == "variant"
                 and "carries no variant key" in i["detail"])],
            [])

    # ---------------------------------------------------------- F6
    def test_every_unplanned_records_fault_is_listed_in_its_own_name(self):
        # The round-41 reviewer's P6 constructions, verbatim:
        # an unplanned competitor descendant-survived record
        # (rep 900, evidenced) and an unplanned competitor
        # output-mismatch record (rep 900, evidenced). Before
        # the fix the round-40 discipline listed only
        # unplanned EXIT faults in their own name: neither
        # fault stood in any fault listing — no competitor
        # entry (correctly: unplanned records mint no
        # evidence) and no campaign entry either. Now every
        # unplanned record's evidenced fault is listed in
        # its own name, under its evidenced predicate, and
        # competitor_losses stays empty for them; the
        # exit-mismatch control renders exactly as before.
        import copy
        recs = complete_records()
        src_k = next(r for r in recs
                     if r["path"] == "kill" and r["arm"] == "nuewframe"
                     and r["context"] == "NO_WINDOW"
                     and r["kind"] == "measured" and r["rep"] == 0)
        fab = copy.deepcopy(src_k)
        fab["rep"] = 900
        fab["outcome"] = "descendant-survived"
        fab["survivor"] = True
        self.assertEqual(
            report_mod.competitor_losses(recs + [fab]), [])
        entries = [loss for loss in report_mod.standing_losses(
            recs + [fab], FULL_COUNTS) if "rep 900" in loss]
        self.assertIn(
            "nuewframe kill path left a descendant alive in "
            "NO_WINDOW rep 900", entries)
        recs = complete_records()
        src_f = next(r for r in recs
                     if r["path"] == "fast" and r["arm"] == "nuewframe"
                     and r["context"] == "NO_WINDOW"
                     and r["kind"] == "measured" and r["rep"] == 0)
        fab = copy.deepcopy(src_f)
        fab["rep"] = 900
        fab["outcome"] = "output-mismatch"
        fab["output_stdout_match"] = False
        self.assertEqual(
            report_mod.competitor_losses(recs + [fab]), [])
        entries = [loss for loss in report_mod.standing_losses(
            recs + [fab], FULL_COUNTS) if "rep 900" in loss]
        self.assertTrue(any(
            loss.startswith(
                "output mismatch in nuewframe/fast/NO_WINDOW "
                "rep 900") for loss in entries), entries)
        recs = complete_records()
        fab = copy.deepcopy(src_f)
        fab["rep"] = 900
        fab["outcome"] = "exit-mismatch"
        fab["exit_code"] = 7
        entries = [loss for loss in report_mod.standing_losses(
            recs + [fab], FULL_COUNTS) if "rep 900" in loss]
        self.assertTrue(any(
            loss.startswith(
                "exit mismatch in nuewframe/fast/NO_WINDOW "
                "rep 900") for loss in entries), entries)
        self.assertEqual(
            report_mod.competitor_losses(recs + [fab]), [])

    # --------------------------------------------- restatements
    def test_verification_restatements_state_the_round41_truths(self):
        # Harness by subject (the restatement test of each
        # landing): VERIFICATION's round-41 statements —
        # item (3)'s multiplicity-exact population, the
        # gate's binding and the own-name fault listings;
        # item (6)'s arm identity against the second
        # encoding, variant-absence naming, one-shot
        # materialization and the placeholder-free breadth
        # of the sequence-token statement.
        import re
        with open(os.path.join(HERE, "..", "VERIFICATION.md"),
                  encoding="utf-8") as handle:
            text = handle.read()
        section3 = text.split(
            "- **(3) CPU", 1)[1].split("- **(4) Scaling", 1)[0]
        section3 = re.sub(r"\s+", " ", section3)
        for needle in ("Round-41 F1", "multiplicity-exact",
                       "Round-41 F2", "label readers",
                       "Round-41 F6", "in its own name"):
            self.assertIn(needle, section3, needle)
        section6 = text.split(
            "- **(6) Security boundaries", 1)[1].split(
            "- **(7) Compatibility", 1)[0]
        section6 = re.sub(r"\s+", " ", section6)
        for needle in ("Round-41 F3", "second encoding",
                       "Round-41 F5", "absence is named",
                       "Round-41 F4", "one-shot",
                       "sequence tokens appended verbatim",
                       "placeholder-free"):
            self.assertIn(needle, section6, needle)


class Round42LandingTests(unittest.TestCase):
    """Round-42 landing (F1-F4): arm identity is held under
    the platform's path semantics (the executable token
    canonicalized, so a respelled pairwise swap names the
    disagreement); F6's own-name listing is kind-complete
    (every unplanned record's evidenced fault listed at
    warmup and control grain as at measured grain);
    materialization never requires a mutable mapping
    (mutation-refusing mappings derive and run, repeated
    derivations agreeing); and the write-back is confined
    to the values that need it (one-shot iterators only —
    values already materialized are never rewritten in
    place)."""

    def shipped_config(self):
        return shipped_config()

    # ---------------------------------------------------------- F1
    def test_arm_identity_is_held_under_the_platforms_path_semantics(self):
        # The round-42 reviewer's P1 constructions, verbatim:
        # the round-41 P3 pairwise arm-label swap (guard and
        # sysprims measured fast NO_WINDOW rep-0 records
        # exchange their arm fields, each keeping its own
        # executed vector) with the kept tokens RESPELLED —
        # uppercase, forward slashes, a ./ prefix, an
        # absolute path: the same binaries under Windows
        # path semantics. Before the fix the F3 limb compared
        # the raw token string, so every respelling rendered
        # pair items [], standing losses 0 and every gate
        # dimension PASS — round 41's P3 invisibility through
        # spelling; the exact-token control rendered 2 items
        # / 2 losses. Now the comparison canonicalizes the
        # executable token (case, separator, relative-prefix
        # and absolute spellings of the same binary agree),
        # so each respelling names the disagreement exactly
        # as the exact-token swap does, while genuinely
        # different binaries still disagree (the two arms'
        # binaries are different, in every spelling), a
        # respelling of the FILED arm's own executable
        # agrees, and a token denoting no arm's executable
        # under that identity is still not named.
        def swap(transform):
            recs = complete_records()
            g = next(r for r in recs
                     if r["arm"] == "guard" and r["path"] == "fast"
                     and r["context"] == "NO_WINDOW"
                     and r["kind"] == "measured" and r["rep"] == 0)
            s = next(r for r in recs
                     if r["arm"] == "sysprims"
                     and r["path"] == "fast"
                     and r["context"] == "NO_WINDOW"
                     and r["kind"] == "measured" and r["rep"] == 0)
            g["argv"] = [transform(g["argv"][0])] + g["argv"][1:]
            s["argv"] = [transform(s["argv"][0])] + s["argv"][1:]
            g["arm"], s["arm"] = "sysprims", "guard"
            items = [i for i in report_mod._record_inconsistencies(recs)
                     if i["record"] in (g, s)
                     and "configured executable of arm" in i["detail"]]
            return recs, items
        for transform in (
                lambda token: token,
                lambda token: token.upper(),
                lambda token: token.replace("\\", "/"),
                lambda token: "./" + token,
                lambda token: "C:\\campaign\\" + token):
            recs, items = swap(transform)
            self.assertEqual(len(items), 2)
            self.assertEqual(report_mod.slot_accounting_losses(recs),
                             [])
            self.assertEqual(
                len(report_mod.standing_losses(recs, FULL_COUNTS)), 2)
        # A single record, no label swap: a guard-filed fast
        # record whose argv[0] is the uppercase sysprims path
        # is named — the token denotes the sysprims binary
        # under the platform's semantics.
        recs = complete_records()
        g = next(r for r in recs
                 if r["arm"] == "guard" and r["path"] == "fast"
                 and r["context"] == "NO_WINDOW"
                 and r["kind"] == "measured" and r["rep"] == 0)
        s_exe = next(r for r in recs
                     if r["arm"] == "sysprims" and r["path"] == "fast"
                     and r["context"] == "NO_WINDOW"
                     and r["kind"] == "measured"
                     and r["rep"] == 0)["argv"][0]
        g["argv"] = [s_exe.upper()] + g["argv"][1:]
        named = [i for i in report_mod._record_inconsistencies(recs)
                 if i["record"] is g
                 and "configured executable of arm" in i["detail"]]
        self.assertEqual(len(named), 1)
        # The filed arm's own executable agrees in every
        # spelling, and a token denoting no arm's executable
        # (the same basename in another directory; the
        # testkit child) is not named.
        for token in ("BUILD\\PROCESS-TREE-GUARD.EXE",
                      "./build/process-tree-guard.exe",
                      "C:\\campaign\\build\\process-tree-guard.exe",
                      "other\\sysprims.exe",
                      "build\\testkit.exe"):
            recs = complete_records()
            g = next(r for r in recs
                     if r["arm"] == "guard" and r["path"] == "fast"
                     and r["context"] == "NO_WINDOW"
                     and r["kind"] == "measured" and r["rep"] == 0)
            g["argv"] = [token] + g["argv"][1:]
            self.assertEqual(
                [i for i in report_mod._record_inconsistencies(recs)
                 if i["record"] is g
                 and "configured executable of arm" in i["detail"]],
                [], token)

    # ---------------------------------------------------------- F2
    def test_every_unplanned_records_fault_is_listed_in_its_own_name_at_every_kind(self):
        # The round-42 reviewer's P2 constructions, verbatim:
        # a duplicate (hence unplanned) warmup competitor
        # record carrying an evidenced output mismatch or
        # descendant survival, an out-of-band warmup record
        # at rep 900 carrying an evidenced survival, and a
        # duplicate control record carrying an evidenced
        # output mismatch. Before the fix the F6
        # fall-throughs carried the measured-kind gate of
        # the evidence branches they mirror (and no branch
        # reached a floor arm's output fault at all): each
        # fault stood in NO fault listing and the faulty
        # duplicate's standing list was byte-identical to a
        # faultless duplicate's. Now every unplanned
        # record's evidenced fault is listed in its own name
        # at warmup and control grain as at measured grain,
        # never as competitor evidence; the planned
        # population's kind discipline is untouched (a
        # planned warmup competitor fault, and a planned
        # control record's, still mint no listing).
        import copy
        def duplicate(pred, mutate):
            recs = complete_records()
            src = next(r for r in recs if pred(r))
            dup = copy.deepcopy(src)
            mutate(dup)
            return recs, dup
        warmup_fast = lambda r: (
            r["arm"] == "nuewframe" and r["path"] == "fast"
            and r["kind"] == "warmup" and r["context"] == "NO_WINDOW")
        warmup_kill = lambda r: (
            r["arm"] == "nuewframe" and r["path"] == "kill"
            and r["kind"] == "warmup" and r["context"] == "NO_WINDOW")
        # Duplicate warmup output mismatch.
        recs, dup = duplicate(warmup_fast, lambda d: d.update(
            {"outcome": "output-mismatch",
             "output_stdout_match": False}))
        faulty = report_mod.standing_losses(recs + [dup], FULL_COUNTS)
        self.assertTrue(any(
            loss.startswith(
                "output mismatch in nuewframe/fast/NO_WINDOW rep ")
            for loss in faulty), faulty)
        self.assertEqual(report_mod.competitor_losses(recs + [dup]),
                         [])
        recs2 = complete_records()
        plain = report_mod.standing_losses(
            recs2 + [copy.deepcopy(
                next(r for r in recs2 if warmup_fast(r)))],
            FULL_COUNTS)
        self.assertNotEqual(plain, faulty)
        # Duplicate warmup descendant survival.
        recs, dup = duplicate(warmup_kill, lambda d: d.update(
            {"outcome": "descendant-survived", "survivor": True}))
        faulty = report_mod.standing_losses(recs + [dup], FULL_COUNTS)
        self.assertTrue(any(
            "kill path left a descendant alive" in loss
            for loss in faulty), faulty)
        self.assertEqual(report_mod.competitor_losses(recs + [dup]),
                         [])
        # Out-of-band warmup survival at rep 900.
        recs, dup = duplicate(warmup_kill, lambda d: d.update(
            {"rep": 900, "outcome": "descendant-survived",
             "survivor": True}))
        entries = [loss for loss in report_mod.standing_losses(
            recs + [dup], FULL_COUNTS) if "rep 900" in loss]
        self.assertIn(
            "nuewframe kill path left a descendant alive in "
            "NO_WINDOW rep 900", entries)
        # Duplicate control output mismatch (floor arm).
        recs, dup = duplicate(
            lambda r: r["kind"] == "control"
            and r["arm"] == "floor-direct",
            lambda d: d.update(
                {"outcome": "output-mismatch",
                 "output_stdout_match": False}))
        faulty = report_mod.standing_losses(recs + [dup], FULL_COUNTS)
        self.assertTrue(any(
            loss.startswith(
                "output mismatch in floor-direct/fast/")
            for loss in faulty), faulty)
        self.assertEqual(report_mod.competitor_losses(recs + [dup]),
                         [])
        # Planned discipline unmoved: the same faults on
        # PLANNED warmup / control records mint no listing.
        for pred, mutate in (
                (warmup_kill, lambda d: d.update(
                    {"outcome": "descendant-survived",
                     "survivor": True})),
                (warmup_fast, lambda d: d.update(
                    {"outcome": "output-mismatch",
                     "output_stdout_match": False})),
                (lambda r: r["kind"] == "control"
                 and r["arm"] == "floor-direct",
                 lambda d: d.update(
                     {"outcome": "output-mismatch",
                      "output_stdout_match": False}))):
            recs = complete_records()
            target = next(r for r in recs if pred(r))
            mutate(target)
            self.assertEqual(
                report_mod.standing_losses(recs, FULL_COUNTS), [])

    # ---------------------------------------------------------- F3
    def test_materialization_never_requires_a_mutable_mapping(self):
        # The round-42 reviewer's P3 constructions, verbatim:
        # configurations carried in mutation-refusing
        # mappings — a MappingProxyType child spec or
        # templates mapping, a frozen dict (a dict subclass
        # whose __setitem__ raises) — carrying generator
        # values. Before the fix the runner's and arms'
        # write-backs raised TypeError on shapes the
        # as-found construction accepted, and where the
        # write-back was isinstance(dict)-guarded it was
        # silently skipped, so a generator template under a
        # proxy mapping derived 5 then 1. Now such
        # configurations derive and run as the as-found
        # construction accepted them, repeated derivations
        # agree, and nothing crashes: the materialized list
        # is carried by the suite-side identity cache where
        # a write-back is refused.
        import copy
        from types import MappingProxyType
        class Frozen(dict):
            def __setitem__(self, key, value):
                raise TypeError("frozen mapping refuses mutation")
        def frozen(mapping):
            out = Frozen()
            for key, value in mapping.items():
                dict.__setitem__(out, key, value)
            return out
        base = shipped_config()
        slot = plan_mod.Slot("measured", "guard", "fast",
                             "NO_WINDOW", 0)
        # Runner: MappingProxyType spec + generator args.
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"] = MappingProxyType({
            "program": cfg["children"]["fast"]["program"],
            "args": (x for x in ["relay", "0"])})
        self.assertEqual(
            runner_mod.child_for(slot, cfg),
            ("build\\testkit.exe", ["relay", "0"]))
        self.assertEqual(
            runner_mod.child_for(slot, cfg),
            ("build\\testkit.exe", ["relay", "0"]))
        # Derivation: the same proxy spec derives, twice,
        # identically to the plain-dict construction (7).
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"] = MappingProxyType({
            "program": cfg["children"]["fast"]["program"],
            "args": (x for x in ["relay", "0"])})
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(
            runner_mod.child_for(slot, cfg),
            ("build\\testkit.exe", ["relay", "0"]))
        # Templates under a MappingProxyType: resolution and
        # derivation agree, first and second (no 5-then-1).
        cfg = copy.deepcopy(base)
        cfg["arms"]["guard"]["templates"] = MappingProxyType(
            {"fast": (t for t in
                      ["{timeout_s}", "{child}", "{child_args}"])})
        self.assertEqual(
            arms_mod.resolve_template("guard", "fast", cfg),
            ["{timeout_s}", "{child}", "{child_args}"])
        self.assertEqual(
            arms_mod.resolve_template("guard", "fast", cfg),
            ["{timeout_s}", "{child}", "{child_args}"])
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        # Frozen spec and frozen templates: no crash, the
        # as-found values, repeated reads agreeing.
        cfg = copy.deepcopy(base)
        spec = frozen(cfg["children"]["fast"])
        dict.__setitem__(spec, "args", (x for x in ["relay", "0"]))
        cfg["children"]["fast"] = spec
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(
            runner_mod.child_for(slot, cfg),
            ("build\\testkit.exe", ["relay", "0"]))
        cfg = copy.deepcopy(base)
        templates = frozen(cfg["arms"]["guard"]["templates"])
        dict.__setitem__(
            templates, "fast",
            (t for t in ["{timeout_s}", "{child}", "{child_args}"]))
        cfg["arms"]["guard"]["templates"] = templates
        self.assertEqual(
            arms_mod.resolve_template("guard", "fast", cfg),
            ["{timeout_s}", "{child}", "{child_args}"])
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))

    # ---------------------------------------------------------- F4
    def test_the_write_back_is_confined_to_the_values_that_need_it(self):
        # The round-42 reviewer's P4 constructions, verbatim:
        # a shipped configuration with one component replaced
        # by a re-iterable non-list value — string args
        # "relay 0", dict args, a tuple template, set args.
        # Before the fix the write-back fired for every
        # non-list value: one derivation rewrote the string
        # into a list of its characters in the caller's
        # object, and the admission failure that object
        # carried disappeared after the derivation — the
        # checker repaired the configuration a second
        # consumer judges. Now only a one-shot iterator is
        # materialized once; values already materialized
        # (strings included) are read locally and never
        # rewritten in place, the judged configuration stands
        # exactly as its owner stated it after any
        # derivation or construction, and the shipped
        # configuration remains byte-identical after a full
        # report run. The one-shot centre is unmoved:
        # generator args still derive 7 then 7 and the
        # runner still sees the full vector.
        import copy
        import harness as harness_mod
        base = shipped_config()
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"]["args"] = "relay 0"
        before = json.dumps(cfg, sort_keys=True)
        adm_before = [f for f in harness_mod.admission_failures(cfg)
                      if "args" in f]
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (12, None))
        self.assertEqual(json.dumps(cfg, sort_keys=True), before)
        self.assertEqual(cfg["children"]["fast"]["args"], "relay 0")
        self.assertEqual(
            [f for f in harness_mod.admission_failures(cfg)
             if "args" in f], adm_before)
        self.assertTrue(adm_before)
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"]["args"] = {"relay": 1, "0": 2}
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(cfg["children"]["fast"]["args"],
                         {"relay": 1, "0": 2})
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"]["args"] = {"relay", "0"}
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(cfg["children"]["fast"]["args"],
                         {"relay", "0"})
        cfg = copy.deepcopy(base)
        cfg["arms"]["guard"]["templates"]["fast"] = (
            "{timeout_s}", "{child}", "{child_args}")
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        self.assertIsInstance(
            cfg["arms"]["guard"]["templates"]["fast"], tuple)
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"]["args"] = \
            (x for x in ["relay", "0"])
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        slot = plan_mod.Slot("measured", "guard", "fast",
                             "NO_WINDOW", 0)
        self.assertEqual(
            runner_mod.child_for(slot, cfg),
            ("build\\testkit.exe", ["relay", "0"]))
        cfg = shipped_config()
        before = json.dumps(cfg, sort_keys=True)
        recs = complete_records()
        report_mod.campaign_losses(recs, FULL_COUNTS, config=cfg)
        report_mod.claim_ledger(recs, config=cfg)
        report_mod.freeze_gate(recs, config=cfg)
        report_mod.render(recs, FULL_COUNTS, {"guard": {}},
                          config=cfg)
        self.assertEqual(json.dumps(cfg, sort_keys=True), before)

