class Round48LandingTests(unittest.TestCase):
    """Round-48 landing (F1-F4): the ambiguous branch's
    verdict is DEFERRED — the confirmation access is
    abolished, no verdict rests on any access beyond
    the reads' own captures at any depth, the ambiguous
    read serves its stated interim (its own tokens when
    non-empty, the entry's when empty), and the
    following read's own capture settles
    storing-vs-minting from captures already taken; a
    raising access at any decision point classifies
    UNDECIDABLE, never silently a minting verdict; the
    breadth is stated at one breadth in VERIFICATION
    and in arms.py's slot docstring, with the
    fresh-traversal mint named outside both; the
    derivation makes no discarded access — no key-set
    iteration, no contains fallback, no second args
    access in its TypeError handler — and its presence
    judgement is made over the same materialized
    evidence the construction builds from."""

    def shipped_config(self):
        return shipped_config()

    # ---------------------------------------------------------- F1
    def test_the_memo_at_confirmation_factory_agrees_in_both_limbs(self):
        # The round-48 reviewer's P1 construction: a
        # factory minting over the one shared source on a
        # mint-mint-memo access cycle — the third access
        # returns the previous mint once, by memo — was
        # classified STORING by the round-47 confirmation
        # access (which was that third access, returning
        # the captured object itself), and diverged
        # full-then-empty in both ambiguous limbs
        # (proven one-shot mints; plain-list mints),
        # spending 4 accesses over 3 reads. There is no
        # confirmation access now: every read spends
        # exactly its own one access, the drained
        # capture stands as an empty candidate served at
        # the entry interim, the memo return settles
        # nothing, and the following fresh mint
        # reproducing the candidate's empty tokens
        # settles MINTING — repeated reads agree in both
        # limbs.
        import copy
        from collections.abc import Mapping
        base = shipped_config()
        tokens = ["relay", "0"]

        class OneShotIterable:
            def __init__(self, under):
                self._gen = under
            def __iter__(self):
                return self._gen

        class MemoConfirmFactory(Mapping):
            def __init__(self, program):
                self._store = {"program": program}
                self._sg = (t for t in tokens)
                self.accesses = 0
                self._last = None
            def __getitem__(self, key):
                if key == "args":
                    self.accesses += 1
                    if self.accesses % 3 == 0 \
                            and self._last is not None:
                        memo = self._last
                        self._last = None
                        return memo
                    gen = (x for x in self._sg)
                    self._last = OneShotIterable(gen)
                    return self._last
                return self._store[key]
            def __iter__(self):
                return iter(list(self._store) + ["args"])
            def __len__(self):
                return len(self._store) + 1

        class MemoListFactory(Mapping):
            def __init__(self, program):
                self._store = {"program": program}
                self._sg = (t for t in tokens)
                self.accesses = 0
                self._last = None
            def __getitem__(self, key):
                if key == "args":
                    self.accesses += 1
                    if self.accesses % 3 == 0 \
                            and self._last is not None:
                        memo = self._last
                        self._last = None
                        return memo
                    self._last = list(self._sg)
                    return self._last
                return self._store[key]
            def __iter__(self):
                return iter(list(self._store) + ["args"])
            def __len__(self):
                return len(self._store) + 1

        spec = MemoConfirmFactory("build\\testkit.exe")
        for _ in range(5):
            self.assertEqual(
                arms_mod.materialized_child_args(spec),
                ["relay", "0"])
        self.assertEqual(spec.accesses, 5)
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"] = MemoConfirmFactory(
            "build\\testkit.exe")
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        spec = MemoListFactory("build\\testkit.exe")
        for _ in range(3):
            self.assertEqual(
                arms_mod.materialized_child_args(spec),
                ["relay", "0"])
        self.assertEqual(spec.accesses, 3)

    # ---------------------------------------------------------- F1
    def test_a_wrapper_stores_replacement_is_reread_and_settles_storing(self):
        # The round-48 reviewer's P2 construction: a
        # storing mapping whose every access returns a
        # fresh WRAPPER around the stored object was
        # classified MINTING by the confirmation access
        # (which returned a further wrapper, never the
        # captured object), and its stated replacement
        # was silently superseded on every consumer. The
        # replacement's capture is non-empty, so it
        # serves its own tokens at the interim on the
        # very read that states it; the following read's
        # fresh wrapper reads the candidate's very
        # traversal and settles STORING — the candidate
        # becomes the entry — and every consumer reads
        # the replacement. No access beyond the reads'
        # own is spent anywhere in the sequence.
        import copy
        from collections.abc import MutableMapping
        base = shipped_config()
        slot = plan_mod.Slot("measured", "guard", "fast",
                             "NO_WINDOW", 0)

        class OneShotIterable:
            def __init__(self, under):
                self._gen = under
            def __iter__(self):
                return self._gen

        class Wrapper:
            def __init__(self, target):
                self._target = target
            def __iter__(self):
                return iter(self._target)

        class WrapperStore(MutableMapping):
            def __init__(self, program, args):
                self._store = {"program": program, "args": args}
                self.accesses = 0
            def __getitem__(self, key):
                value = self._store[key]
                if key == "args":
                    self.accesses += 1
                    return Wrapper(value)
                return value
            def __setitem__(self, key, value):
                self._store[key] = value
            def __delitem__(self, key):
                del self._store[key]
            def __iter__(self):
                return iter(list(self._store))
            def __len__(self):
                return len(self._store)

        cfg = copy.deepcopy(base)
        spec = WrapperStore(
            "build\\testkit.exe",
            OneShotIterable((t for t in ["relay", "0"])))
        cfg["children"]["fast"] = spec
