    # ---------------------------------------------------------- F1
    def test_a_raising_decision_access_is_undecidable_never_a_minting_verdict(self):
        # The round-48 reviewer's P3 construction: a
        # storing store whose confirmation access raised
        # RuntimeError had the raise absorbed to _MISSING
        # at the confirmation site and thereby to a
        # MINTING verdict — its stated replacement
        # superseded with no naming anywhere. There is no
        # confirmation access and no absorption at any
        # decision site now: the replacement serves its
        # own tokens at the interim, a re-stated
        # replacement reproducing the candidate's
        # non-empty tokens settles STORING for the
        # derivation, and a read whose own capture access
        # raises propagates the raise exactly as one
        # honest read does (the UNDECIDABLE face: no
        # verdict is taken at all).
        import copy
        from collections.abc import MutableMapping
        base = shipped_config()

        class OneShotIterable:
            def __init__(self, under):
                self._gen = under
            def __iter__(self):
                return self._gen

        class RaisingConfirmStore(MutableMapping):
            def __init__(self, program, args):
                self._store = {"program": program, "args": args}
                self._armed = True
                self.accesses = 0
            def __getitem__(self, key):
                if key == "args":
                    self.accesses += 1
                    if self._armed:
                        self._armed = False
                        return self._store[key]
                    raise RuntimeError("confirmation access fails")
                return self._store[key]
            def __setitem__(self, key, value):
                self._store[key] = value
                self._armed = True
            def __delitem__(self, key):
                del self._store[key]
            def __iter__(self):
                return iter(list(self._store))
            def __len__(self):
                return len(self._store)

        cfg = copy.deepcopy(base)
        spec = RaisingConfirmStore(
            "build\\testkit.exe",
            OneShotIterable((t for t in ["relay", "0"])))
        cfg["children"]["fast"] = spec
        self.assertEqual(arms_mod.materialized_child_args(spec),
                         ["relay", "0"])
        spec["args"] = OneShotIterable(
            (t for t in ["new1", "new2", "new3"]))
        self.assertEqual(arms_mod.materialized_child_args(spec),
                         ["new1", "new2", "new3"])
        self.assertEqual(spec.accesses, 2)
        spec["args"] = OneShotIterable(
            (t for t in ["new1", "new2", "new3"]))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (8, None))
        fresh = RaisingConfirmStore(
            "build\\testkit.exe",
            OneShotIterable((t for t in ["relay", "0"])))
        self.assertEqual(arms_mod.materialized_child_args(fresh),
                         ["relay", "0"])
        with self.assertRaises(RuntimeError):
            arms_mod.materialized_child_args(fresh)

    # ---------------------------------------------------------- F1
    def test_no_decision_access_spends_over_a_source_no_capture_held(self):
        # The round-48 reviewer's P4 construction: a
        # two-source factory whose round-47 confirmation
        # access minted an eager list over a second
        # source (SB) the read's capture — over SA —
        # never held, draining SB so no later read ever
        # rendered its tokens, against VERIFICATION's
        # confinement sentence. The decision now spends
        # no access at all: two reads spend exactly two
        # accesses, SB stands undrained after the
        # ambiguous read (which serves the entry at the
        # empty candidate's interim), and the following
        # read — its own mint over SB — renders SB's
        # tokens in full.
        import copy
        from collections.abc import Mapping
        base = shipped_config()
        tokens = ["relay", "0"]
        new = ["new1", "new2", "new3"]

        class OneShotIterable:
            def __init__(self, under):
                self._gen = under
            def __iter__(self):
                return self._gen

        class TwoSourceFactory(Mapping):
            def __init__(self, program):
                self._store = {"program": program}
                self.sa = (t for t in tokens)
                self.sb = (t for t in new)
                self.accesses = 0
            def __getitem__(self, key):
                if key == "args":
                    self.accesses += 1
                    if self.accesses == 1:
                        return OneShotIterable(self.sa)
                    if self.accesses == 2:
                        return OneShotIterable(
                            (x for x in self.sa))
                    if self.accesses == 3:
                        return list(self.sb)
                    return OneShotIterable(self.sb)
                return self._store[key]
            def __iter__(self):
                return iter(list(self._store) + ["args"])
            def __len__(self):
                return len(self._store) + 1

        cfg = copy.deepcopy(base)
        spec = TwoSourceFactory("build\\testkit.exe")
        cfg["children"]["fast"] = spec
        self.assertEqual(arms_mod.materialized_child_args(spec),
                         ["relay", "0"])
        self.assertEqual(arms_mod.materialized_child_args(spec),
                         ["relay", "0"])
        self.assertEqual(spec.accesses, 2)
        self.assertEqual(arms_mod.materialized_child_args(spec),
                         ["new1", "new2", "new3"])
        self.assertEqual(spec.accesses, 3)

    # ---------------------------------------------------------- F2
    def test_the_fresh_traversal_mint_stands_outside_the_stated_breadth(self):
        # The round-48 reviewer's P5 construction: a
        # factory whose every access mints a wrapper
        # whose iter() mints a FRESH generator over the
        # one shared source — one-shot in effect (one
        # minted value read twice honestly renders full
        # then empty), but no traversal object is ever
        # handed back twice, so no capture is proven and
        # no identity limb can recognise the mint. Round
        # 48 F2 names this carrier outside the one
        # breadth VERIFICATION and arms.py's slot
        # docstring state, in both alike: its reads stand
        # on the storing face — the first capture in
        # full, then the drained remainder. The variant
        # whose second iter() raises is the control: the
        # raise is absorbed as unproven exactly as the
        # named class's is, and the same face serves.
        import copy
        from collections.abc import Mapping
        base = shipped_config()
        tokens = ["relay", "0"]

        class FreshGenWrapper:
            def __init__(self, source):
                self._source = source
            def __iter__(self):
                return (x for x in self._source)

        class FreshGenFactory(Mapping):
            def __init__(self, program):
                self._store = {"program": program}
                self._sg = (t for t in tokens)
            def __getitem__(self, key):
                if key == "args":
                    return FreshGenWrapper(self._sg)
                return self._store[key]
            def __iter__(self):
                return iter(list(self._store) + ["args"])
            def __len__(self):
                return len(self._store) + 1

        class RaisingSecondWrapper:
            def __init__(self, source):
                self._source = source
                self.calls = 0
            def __iter__(self):
                self.calls += 1
                if self.calls == 2:
                    raise RuntimeError("second iter raises")
                return (x for x in self._source)

        class RaisingSecondFactory(Mapping):
            def __init__(self, program):
                self._store = {"program": program}
                self._sg = (t for t in tokens)
            def __getitem__(self, key):
                if key == "args":
                    return RaisingSecondWrapper(self._sg)
                return self._store[key]
            def __iter__(self):
                return iter(list(self._store) + ["args"])
            def __len__(self):
                return len(self._store) + 1

        spec = FreshGenFactory("build\\testkit.exe")
        self.assertEqual(
            (arms_mod.materialized_child_args(spec),
             arms_mod.materialized_child_args(spec),
             arms_mod.materialized_child_args(spec)),
            (["relay", "0"], [], []))
        cfg = copy.deepcopy(base)
        cfg["children"]["fast"] = FreshGenFactory(
            "build\\testkit.exe")
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (7, None))
        self.assertEqual(
            report_mod._plan_fast_argv_derivation("guard", cfg),
            (5, None))
        minted = FreshGenFactory("p").get("args")
        self.assertEqual((list(minted), list(minted)),
                         (["relay", "0"], []))
        spec = RaisingSecondFactory("build\\testkit.exe")
        self.assertEqual(
            (arms_mod.materialized_child_args(spec),
             arms_mod.materialized_child_args(spec)),
            (["relay", "0"], []))

